3	import { useState } from "react";
4	import { createPortal } from "react-dom";
5	import styles from "./score.module.css";
6	import { computeSkins } from "@/lib/v2/rounds/skins";
7	import { computeNassau } from "@/lib/v2/rounds/nassau";
8	import { computeSixSixSix, sixesNetUnits } from "@/lib/v2/rounds/sixes";
9	import { computeVegas, vegasNet, type VegasHole } from "@/lib/v2/rounds/vegas";
10	import { settleUp } from "@/lib/v2/rounds/settle";
11	import GameSettingsModal from "./GameSettingsModal";
12	
13	const firstName = (name: string) => name.trim().split(/\s+/)[0] || name;
14	
15	export interface RoundGame {
16	  id: string;
17	  game_type: string;
18	  is_net: boolean;
19	  participant_ids: string[];
20	  value: number | null; // optional $ stake per skin / per bet
21	  carry?: boolean; // skins only — roll tied skins to the next hole (default off)
22	}
23	
24	const money = (n: number) => `$${n % 1 === 0 ? n : n.toFixed(2)}`;
25	
26	function GearButton({ onClick }: { onClick: () => void }) {
27	  return (
28	    <button type="button" className={styles.sideGameGear} onClick={onClick} aria-label="Game settings">
29	      <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round">
30	        <circle cx="12" cy="12" r="3" />
31	        <path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z" />
32	      </svg>
33	    </button>
34	  );
35	}
36	
37	/**
38	 * Settlement rendered as boxes only: one box per player who owes, each showing the
39	 * amount stacked over the small recipient name(s). Shared by 6-6-6 and Vegas.
40	 */
41	function DebtBoxes({ netById, playerNames }: { netById: Record<string, number>; playerNames: Record<string, string> }) {
42	  const transfers = settleUp(netById);
43	  if (transfers.length === 0) return <div className={styles.sideGameSettle}>All square</div>;
44	  const byPayer = new Map<string, { to: string; amount: number }[]>();
45	  for (const t of transfers) {
46	    if (!byPayer.has(t.from)) byPayer.set(t.from, []);
47	    byPayer.get(t.from)!.push({ to: t.to, amount: t.amount });
48	  }
49	  return (
50	    <div className={`${styles.sideGameGrid} ${styles.sixesDebts}`}>
51	      {[...byPayer.entries()].map(([from, list]) => (
52	        <div key={from} className={styles.sideGameTile} data-settle="down">
53	          <div className={styles.sideGameTileTop}>
54	            <span className={styles.sideGameTileName}>{playerNames[from] || "Player"} owes</span>
55	          </div>
56	          <div className={styles.sideGamePayRow}>
57	            {list.map((t, i) => (
58	              <span key={i} className={styles.sideGamePayChip}>
59	                <span className={styles.sideGamePayAmt}>{money(t.amount)}</span>
60	                <span className={styles.sideGamePayTo}>{firstName(playerNames[t.to] || "")}</span>
61	              </span>
62	            ))}
63	          </div>
64	        </div>
65	      ))}
66	    </div>
67	  );
68	}
69	
70	/**
71	 * Live side-game standings on the scorer (#183). Derived from the current scores,
72	 * so it re-computes on every entry. Each card has a gear to edit stake, gross/net,
73	 * or roster mid-round.
74	 */
75	export default function SideGameStandings({
76	  games,
77	  playerNames,
78	  holeNumbers,
79	  gross,
80	  strokesByPlayer = {},
81	  parByHole = {},
82	  roundId,
83	  rosterOrder,
84	  brandColor = "#0a5c36",
85	  readOnly = false,
86	  onGameSaved,
87	  onGameRemoved,
88	}: {
89	  games: RoundGame[];
90	  playerNames: Record<string, string>;
91	  holeNumbers: number[];
92	  gross: Record<string, Record<number, number>>;
93	  strokesByPlayer?: Record<string, Record<number, number>>;
94	  parByHole?: Record<number, number>;
95	  roundId: string;
96	  rosterOrder: string[];
97	  brandColor?: string;
98	  readOnly?: boolean; // completed-round detail: show results, no editing
99	  onGameSaved?: (g: RoundGame) => void;
100	  onGameRemoved?: (id: string) => void;
101	}) {
102	  const [editing, setEditing] = useState<RoundGame | null>(null);
103	  const [vegasPop, setVegasPop] = useState<{ ph: VegasHole; teamA: string[]; teamB: string[]; x: number; y: number } | null>(null);
104	  const skins = games.filter((g) => g.game_type === "skins");
105	  const nassau = games.filter((g) => g.game_type === "nassau");
106	  const sixes = games.filter((g) => g.game_type === "sixes");
107	  const vegas = games.filter((g) => g.game_type === "vegas");
108	  if (skins.length === 0 && nassau.length === 0 && sixes.length === 0 && vegas.length === 0) return null;
109	
110	  // Net: subtract each player's per-hole handicap strokes before scoring.
111	  const netScores = (): Record<string, Record<number, number>> => {
112	    const out: Record<string, Record<number, number>> = {};
113	    for (const pid in gross) {
114	      const m: Record<number, number> = {};
115	      for (const h in gross[pid]) {
116	        const strokes = strokesByPlayer[pid]?.[Number(h)] ?? 0;
117	        m[Number(h)] = gross[pid][Number(h)] - strokes;
118	      }
119	      out[pid] = m;
120	    }
121	    return out;
122	  };
123	
124	  return (
125	    <div className={styles.sideGames}>
126	      {skins.map((g) => {
127	        const scores = g.is_net ? netScores() : gross;
128	        const r = computeSkins(holeNumbers, scores, g.participant_ids, g.carry === true);
129	        // Each skin is worth `stake` from every OTHER player, so a player's net is
130	        // stake × (theirSkins × N − totalSkins). Sums to zero across the table.
131	        const n = g.participant_ids.length;
132	        const totalSkins = g.participant_ids.reduce((sum, id) => sum + (r.wonBy[id] ?? 0), 0);
133	        const standings = g.participant_ids
134	          .map((id) => {
135	            const won = r.wonBy[id] ?? 0;
136	            return { id, name: playerNames[id] || "Player", won, net: g.value ? g.value * (won * n - totalSkins) : 0 };
137	          })
138	          .sort((a, b) => b.won - a.won);
139	        return (
140	          <div key={g.id} className={styles.sideGame}>
141	            <div className={styles.sideGameHead}>
142	              <span className={styles.sideGameTitle}>
143	                Skins{g.is_net ? " (Net)" : ""}
144	                {g.value ? <span className={styles.sideGameStake}> {money(g.value)}/skin</span> : null}
145	              </span>
146	              {r.carrying > 0 && <span className={styles.sideGameCarry}>{r.carrying} carrying</span>}
147	              <span className={styles.sideGameThru}>{r.resolved > 0 ? `thru ${r.resolved}` : "not started"}</span>
148	              {!readOnly && <GearButton onClick={() => setEditing(g)} />}
149	            </div>
150	            <div className={styles.sideGameGrid}>
151	              {standings.map((s) => (
152	                <div key={s.id} className={styles.sideGameTile}>
153	                  <div className={styles.sideGameTileTop}>
154	                    <span className={styles.sideGameTileName}>{s.name}</span>
155	                    {g.value ? <span className={styles.sideGameTileSkins}>{s.won === 1 ? "1 skin" : `${s.won} skins`}</span> : null}
156	                  </div>
157	                  {g.value ? (
158	                    <span className={s.net > 0 ? styles.sideGameTileUp : s.net < 0 ? styles.sideGameTileDown : styles.sideGameTileEven}>
159	                      {money(Math.abs(s.net))}
160	                    </span>
161	                  ) : (
162	                    <span className={styles.sideGameTileEven}>
163	                      {s.won} <span className={styles.sideGameTileSkinsInline}>{s.won === 1 ? "skin" : "skins"}</span>
164	                    </span>
165	                  )}
166	                </div>
167	              ))}
168	            </div>
169	          </div>
170	        );
171	      })}
172	
173	      {nassau.map((g) => {
174	        const [a, b] = g.participant_ids;
175	        if (!a || !b) {
176	          return (
177	            <div key={g.id} className={styles.sideGame}>
178	              <div className={styles.sideGameHead}>
179	                <span className={styles.sideGameTitle}>Nassau{g.is_net ? " (Net)" : ""}</span>
180	                <span className={styles.sideGameThru} />
181	                {!readOnly && <GearButton onClick={() => setEditing(g)} />}
182	              </div>
183	              <div className={styles.sideGameRows}>
184	                <span className={styles.sideGameName}>Needs two players.</span>
185	              </div>
186	            </div>
187	          );
188	        }
189	        const scores = g.is_net ? netScores() : gross;
190	        const r = computeNassau(holeNumbers, scores, a, b);
191	        // Each segment is its own bet worth the stake; net them into one settlement.
192	        let net = 0; // + = a ahead in dollars
193	        if (g.value) {
194	          for (const s of r.segments) {
195	            if (s.leader === a) net += g.value;
196	            else if (s.leader === b) net -= g.value;
197	          }
198	        }
199	        const winner = net > 0 ? a : b;
200	        const loser = net > 0 ? b : a;
201	        return (
202	          <div key={g.id} className={styles.sideGame}>
203	            <div className={styles.sideGameHead}>
204	              <span className={styles.sideGameTitle}>
205	                {firstName(playerNames[a] || "A")} v {firstName(playerNames[b] || "B")}
206	                <span className={styles.sideGameStake}> ({g.is_net ? "Net" : "Raw"})</span>
207	              </span>
208	              <span className={styles.sideGameThru}>
209	                Nassau
210	                {g.value ? <span className={styles.sideGameStake}> {money(g.value)}/bet</span> : null}
211	              </span>
212	              {!readOnly && <GearButton onClick={() => setEditing(g)} />}
213	            </div>
214	            <div className={styles.sideGameSegs} data-single={r.segments.length === 1 || undefined}>
215	              {r.segments.map((s) => {
216	                const name = s.leader ? firstName(playerNames[s.leader] || "") : "";
217	                const text = !s.leader
218	                  ? "AS"
219	                  : s.closeout
220	                    ? `${name} ${s.up}&${s.remaining}`
221	                    : s.complete
222	                      ? `${name} ${s.up} up`
223	                      : `${name} ${s.up}▲`;
224	                return (
225	                  <div key={s.key} className={styles.sideGameSeg}>
226	                    <span className={styles.sideGameSegLabel}>{s.label}</span>
227	                    <span className={s.leader ? styles.sideGameSegVal : styles.sideGameSegSquare}>{text}</span>
228	                    {s.dormie && <span className={styles.sideGameDormie}>dormie</span>}
229	                    {s.decided && s.leader && <span className={styles.sideGameFinal}>final</span>}
230	                  </div>
231	                );
232	              })}
233	            </div>
234	            {g.value && (
235	              <div className={styles.sideGameSettle}>
236	                {net !== 0
237	                  ? `${firstName(playerNames[loser] || "")} pays ${firstName(playerNames[winner] || "")} ${money(Math.abs(net))}`
238	                  : "All square"}
239	              </div>
240	            )}
241	          </div>
242	        );
243	      })}
244	
245	      {sixes.map((g) => {
246	        const scores = g.is_net ? netScores() : gross;
247	        const players = g.participant_ids;
248	        if (players.length !== 4) {
249	          return (
