296	                      <span className={styles.sixesVs}> v </span>
297	                      <span className={bWin ? styles.sixesTeamWin : undefined}>{teamLabel(s.teamB)}</span>
298	                    </div>
299	                  </div>
300	                );
301	              })}
302	            </div>
303	            {units && <DebtBoxes netById={Object.fromEntries(players.map((id) => [id, (units[id] ?? 0) * (g.value ?? 0)]))} playerNames={playerNames} />}
304	          </div>
305	        );
306	      })}
307	
308	      {vegas.map((g) => {
309	        const scores = g.is_net ? netScores() : gross;
310	        const players = g.participant_ids;
311	        if (players.length !== 4) {
312	          return (
313	            <div key={g.id} className={styles.sideGame}>
314	              <div className={styles.sideGameHead}>
315	                <span className={styles.sideGameTitle}>Vegas</span>
316	                <span className={styles.sideGameThru} />
317	                {!readOnly && <GearButton onClick={() => setEditing(g)} />}
318	              </div>
319	              <div className={styles.sideGameRows}>
320	                <span className={styles.sideGameName}>Needs four players.</span>
321	              </div>
322	            </div>
323	          );
324	        }
325	        const teamLabel = (t: string[]) => `${firstName(playerNames[t[0]] || "")}+${firstName(playerNames[t[1]] || "")}`;
326	        const r = computeVegas(holeNumbers, scores, parByHole, players);
327	        const aWin = r.leader === "A";
328	        const bWin = r.leader === "B";
329	        const netById = g.value ? vegasNet(r, g.value) : null;
330	        return (
331	          <div key={g.id} className={styles.sideGame}>
332	            <div className={styles.sideGameHead}>
333	              <span className={styles.sideGameTitle}>
334	                Vegas
335	                <span className={styles.sideGameStake}> ({g.is_net ? "Net" : "Raw"})</span>
336	              </span>
337	              <span className={styles.sideGameThru}>
338	                {g.value ? <span className={styles.sideGameStake}>{money(g.value)}/pt</span> : null}
339	              </span>
340	              {!readOnly && <GearButton onClick={() => setEditing(g)} />}
341	            </div>
342	            <div className={styles.sixesMatch}>
343	              <span className={aWin ? styles.sixesTeamWin : undefined}>
344	                {teamLabel(r.teamA)} {r.aTotal}
345	              </span>
