353	                {r.perHole.map((ph) => (
354	                  <button
355	                    key={ph.hole}
356	                    type="button"
357	                    className={styles.vegasHole}
358	                    onClick={(e) => setVegasPop({ ph, teamA: r.teamA, teamB: r.teamB, x: e.clientX, y: e.clientY })}
359	                  >
360	                    <span className={styles.vegasHoleNum}>{ph.hole}</span>
361	                    <span className={styles.vegasHoleDiff} data-team={ph.leader ? ph.leader.toLowerCase() : undefined}>
362	                      {ph.leader ? ph.diff : "–"}
363	                    </span>
364	                  </button>
365	                ))}
366	                <div className={`${styles.vegasHole} ${styles.vegasTotal}`}>
367	                  <span className={styles.vegasHoleNum}>T</span>
368	                  <span className={styles.vegasHoleDiff} data-team={r.leader ? r.leader.toLowerCase() : undefined}>
369	                    {r.leader ? r.points : "–"}
370	                  </span>
371	                </div>
372	              </div>
373	            )}
374	            {netById && <DebtBoxes netById={netById} playerNames={playerNames} />}
375	          </div>
376	        );
377	      })}
378	
379	      {editing && (
380	        <GameSettingsModal
381	          game={editing}
382	          playerNames={playerNames}
383	          rosterOrder={rosterOrder}
384	          roundId={roundId}
385	          brandColor={brandColor}
386	          onSaved={(g) => {
387	            onGameSaved?.(g);
388	            setEditing(null);
389	          }}
390	          onRemoved={(id) => {
391	            onGameRemoved?.(id);
392	            setEditing(null);
393	          }}
394	          onClose={() => setEditing(null)}
395	        />
396	      )}
397	
398	      {vegasPop &&
399	        createPortal(
400	          <div className={styles.vegasPopBackdrop} onClick={() => setVegasPop(null)}>
401	            {(() => {
402	              const { ph, teamA, teamB, x, y } = vegasPop;
403	              const line = (ids: string[], scoresPair: [number, number], num: number, flip: boolean) => (
404	                <div className={styles.vegasPopLine}>
405	                  <span>
406	                    {firstName(playerNames[ids[0]] || "")} {scoresPair[0]}, {firstName(playerNames[ids[1]] || "")} {scoresPair[1]}
407	                  </span>
408	                  <span className={styles.vegasPopNum}>
409	                    → {num}
410	                    {flip && <span className={styles.vegasPopFlip}> flip</span>}
411	                  </span>
412	                </div>
413	              );
414	              const winTeam = ph.leader === "A" ? teamA : ph.leader === "B" ? teamB : null;
415	              const winLabel = winTeam ? `${firstName(playerNames[winTeam[0]] || "")}+${firstName(playerNames[winTeam[1]] || "")}` : null;
416	              const clampedX = Math.min(Math.max(x, 96), (typeof window !== "undefined" ? window.innerWidth : 400) - 96);
417	              return (
418	                <div
419	                  className={styles.vegasPop}
420	                  style={{ left: clampedX, top: Math.max(8, y - 12) }}
