424	                  {line(teamA, ph.aScores, ph.aNum, ph.aFlip)}
425	                  {line(teamB, ph.bScores, ph.bNum, ph.bFlip)}
426	                  <div className={styles.vegasPopResult}>
427	                    {winLabel ? `${ph.diff} pt${ph.diff === 1 ? "" : "s"} to ${winLabel}` : "Tied — 0 pts"}
428	                  </div>
429	                </div>
