"use client";

import { useState } from "react";
import styles from "@/app/new/new.module.css";
import Modal from "@/app/new/_components/Modal";
import ConfirmModal from "@/app/new/_components/ConfirmModal";

export interface ContestPlayer {
  user_id: string;
  name: string;
}
export interface ContestCandidate {
  user_id: string;
  name: string;
  attending: boolean;
}

/**
 * Manage a contest's players (#215). Import everyone attending, add specific
 * members (even non-attendees — a drop-in), or remove someone (who stays on the
 * event roster but is tombstoned so attendance-sync won't re-add them).
 */
export default function ContestPlayers({
  orgId,
  eventId,
  contestId,
  initialPlayers,
  members,
}: {
  orgId: string;
  eventId: string;
  contestId: string;
  initialPlayers: ContestPlayer[];
  members: ContestCandidate[];
}) {
  const base = `/api/v2/orgs/${orgId}/events/${eventId}/contests/${contestId}/participants`;
  const [players, setPlayers] = useState<ContestPlayer[]>(initialPlayers);
  const [busy, setBusy] = useState(false);
  const [addOpen, setAddOpen] = useState(false);
  const [q, setQ] = useState("");
  const [sel, setSel] = useState<Set<string>>(new Set());
  const [removing, setRemoving] = useState<ContestPlayer | null>(null);

  async function reload() {
    const res = await fetch(base);
    if (!res.ok) return;
    const d = await res.json();
    setPlayers(
      (d.participants || []).map((p: { user_id: string; display_name: string | null; first_name: string | null; last_name: string | null }) => ({
        user_id: p.user_id,
        name: p.display_name || `${p.first_name || ""} ${p.last_name || ""}`.trim() || "Member",
      })),
    );
  }

  const playerIds = new Set(players.map((p) => p.user_id));
  const candidates = members.filter((m) => !playerIds.has(m.user_id));
  const attendingToAdd = candidates.filter((m) => m.attending).length;
  const query = q.trim().toLowerCase();
  const shown = query ? candidates.filter((m) => m.name.toLowerCase().includes(query)) : candidates;

  async function post(body: Record<string, unknown>) {
    if (busy) return;
    setBusy(true);
    try {
      const res = await fetch(base, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
      if (res.ok) {
        await reload();
        setSel(new Set());
        setAddOpen(false);
        setQ("");
      }
    } finally {
      setBusy(false);
    }
  }

  async function confirmRemove() {
    if (!removing || busy) return;
    setBusy(true);
    try {
      const res = await fetch(base, { method: "DELETE", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ userIds: [removing.user_id] }) });
      if (res.ok) {
        await reload();
        setRemoving(null);
      }
    } finally {
      setBusy(false);
    }
  }

  function toggle(id: string) {
    setSel((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }

  return (
    <div className={styles.section}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8 }}>
        <p className={styles.sectionLabel} style={{ margin: 0 }}>Players ({players.length})</p>
        <button type="button" className={styles.createBtnGhost} onClick={() => setAddOpen(true)}>
          Add players
        </button>
      </div>

      {players.length === 0 ? (
        <p className={styles.roundFormHint} style={{ marginTop: 8 }}>
          No players yet. Add everyone attending, or pick specific members.
        </p>
      ) : (
        <div className={styles.memberList} style={{ marginTop: 10 }}>
          {players.map((p) => (
            <div key={p.user_id} className={styles.memberRow}>
              <span className={styles.memberAvatar} aria-hidden>{(p.name[0] || "?").toUpperCase()}</span>
              <div className={styles.memberMeta} style={{ minWidth: 0 }}>
                <div className={styles.memberName}>{p.name}</div>
              </div>
              <button type="button" className={styles.removeBtn} onClick={() => setRemoving(p)} disabled={busy}>
                Remove
              </button>
            </div>
          ))}
        </div>
      )}

      <Modal open={addOpen} title="Add players" onClose={() => (busy ? undefined : setAddOpen(false))}>
        <button
          type="button"
          className={styles.createBtn}
          onClick={() => post({ importAll: true })}
          disabled={busy || attendingToAdd === 0}
          style={{ width: "100%", opacity: busy || attendingToAdd === 0 ? 0.6 : 1 }}
        >
          Add everyone attending{attendingToAdd ? ` (${attendingToAdd})` : ""}
        </button>
        <p className={styles.roundFormHint} style={{ margin: "14px 0 6px" }}>Or pick specific members (a local drop-in need not be attending):</p>
        <input className={styles.input} placeholder="Search members…" value={q} onChange={(e) => setQ(e.target.value)} />
        <div className={styles.simList} style={{ maxHeight: 320, marginTop: 6 }}>
          {shown.map((m) => (
            <button
              key={m.user_id}
              type="button"
              className={styles.simMember}
              data-current={sel.has(m.user_id) || undefined}
              onClick={() => toggle(m.user_id)}
              disabled={busy}
            >
              <span className={styles.simMemberAvatarFallback}>{(m.name[0] || "?").toUpperCase()}</span>
              <span className={styles.simMemberName}>{m.name}</span>
              {m.attending && <span className={styles.roleBadge}>attending</span>}
              {sel.has(m.user_id) && <span aria-hidden>✓</span>}
            </button>
          ))}
          {shown.length === 0 && <p className={styles.roundFormHint}>No members to add.</p>}
        </div>
        {sel.size > 0 && (
          <button type="button" className={styles.createBtn} onClick={() => post({ userIds: [...sel] })} disabled={busy} style={{ width: "100%", marginTop: 12 }}>
            Add {sel.size} selected
          </button>
        )}
      </Modal>

      <ConfirmModal
        open={!!removing}
        destructive
        title="Remove player?"
        message={removing ? `${removing.name} will be removed from this contest. They stay attending the event, but won't be auto-re-added here.` : ""}
        confirmLabel="Remove"
        onConfirm={confirmRemove}
        onCancel={() => (busy ? undefined : setRemoving(null))}
      />
    </div>
  );
}

