1	"use client";
2	
3	import { useMemo, useRef, useState } from "react";
4	import ConfirmModal from "@/app/new/_components/ConfirmModal";
5	import { fmtTime } from "@/lib/v2/schedule";
6	import styles from "@/app/new/new.module.css";
7	/* eslint-disable @next/next/no-img-element */
8	
9	export interface Participant {
10	  user_id: string;
11	  display_name: string | null;
12	  first_name: string | null;
13	  last_name: string | null;
14	  avatar_url: string | null;
15	}
16	export interface TeamData {
17	  id: string;
18	  name: string | null;
19	  team_handicap: number | null;
20	  tee_time: string | null;
21	  members: string[];
22	}
23	interface LocalTeam {
24	  key: string;
25	  name: string;
26	  handicap: number | null;
27	  tee_time: string; // HH:MM
28	  members: string[];
29	}
30	interface HcpBreakdown {
31	  team_handicap: number;
32	  members: { user_id: string; handicap_index: number | null; course_handicap: number; weight: number; contribution: number }[];
33	}
34	
35	const SIZES = [2, 3, 4];
36	
37	function shuffle<T>(arr: T[]): T[] {
38	  const a = [...arr];
39	  for (let i = a.length - 1; i > 0; i--) {
40	    const j = Math.floor(Math.random() * (i + 1));
41	    [a[i], a[j]] = [a[j], a[i]];
42	  }
43	  return a;
44	}
45	
46	export default function TeamsManager({
47	  orgId,
48	  eventId,
49	  contestId,
50	  participants,
51	  initialTeams,
52	  contestStartTime,
53	}: {
54	  orgId: string;
55	  eventId: string;
56	  contestId: string;
57	  participants: Participant[];
58	  initialTeams: TeamData[];
59	  contestStartTime: string | null;
60	}) {
61	  const keySeq = useRef(0);
62	  const nextKey = () => `t${keySeq.current++}`;
63	  const startHHMM = contestStartTime ? contestStartTime.slice(0, 5) : "";
64	
65	  const [teams, setTeams] = useState<LocalTeam[]>(() =>
66	    initialTeams.map((t) => ({
67	      key: nextKey(),
68	      name: t.name || "",
69	      handicap: t.team_handicap,
70	      tee_time: t.tee_time ? t.tee_time.slice(0, 5) : "",
71	      members: [...t.members],
72	    })),
73	  );
74	  const [teamSize, setTeamSize] = useState(4);
75	  const [selected, setSelected] = useState<Set<string>>(new Set());
76	  const [dirty, setDirty] = useState(false);
77	  const [saving, setSaving] = useState(false);
78	  const [calcBusy, setCalcBusy] = useState(false);
79	  const [missingCount, setMissingCount] = useState(0);
80	  const [breakdowns, setBreakdowns] = useState<Record<string, HcpBreakdown>>({});
81	  const [calcTeeName, setCalcTeeName] = useState<string | null>(null);
82	  const [expanded, setExpanded] = useState<Set<string>>(new Set());
83	  const [error, setError] = useState<string | null>(null);
84	  const [confirmGen, setConfirmGen] = useState(false);
85	
86	  const profileById = useMemo(() => new Map(participants.map((p) => [p.user_id, p])), [participants]);
87	  const name = (uid: string) => {
88	    const p = profileById.get(uid);
89	    return p ? p.display_name || `${p.first_name || ""} ${p.last_name || ""}`.trim() || "Member" : "Member";
90	  };
91	  const assigned = useMemo(() => new Set(teams.flatMap((t) => t.members)), [teams]);
92	  const unassigned = participants.filter((p) => !assigned.has(p.user_id));
93	
94	  const selectedIds = useMemo(() => [...selected], [selected]);
95	  const hasSel = selected.size > 0;
96	  const addLabel = selected.size === 1 ? name(selectedIds[0]) : `${selected.size} players`;
97	  function toggleSel(id: string) {
98	    setSelected((prev) => { const n = new Set(prev); if (n.has(id)) n.delete(id); else n.add(id); return n; });
99	  }
100	  function clearSel() { setSelected(new Set()); }
101	
102	  function mutate(fn: (draft: LocalTeam[]) => LocalTeam[]) {
103	    setTeams((prev) => fn(prev.map((t) => ({ ...t, members: [...t.members] }))));
104	    setBreakdowns({}); // any team edit makes a prior calculation stale
105	    setExpanded(new Set());
106	    setDirty(true);
107	  }
108	  function toggleExpand(key: string) {
109	    setExpanded((prev) => { const n = new Set(prev); if (n.has(key)) n.delete(key); else n.add(key); return n; });
110	  }
111	
112	  function doGenerate() {
113	    const ids = shuffle(participants.map((p) => p.user_id));
114	    const n = Math.max(1, Math.ceil(ids.length / teamSize));
115	    const buckets: string[][] = Array.from({ length: n }, () => []);
116	    ids.forEach((id, i) => buckets[i % n].push(id));
117	    keySeq.current = 0;
118	    setTeams(buckets.map((members, i) => ({ key: nextKey(), name: "", handicap: null, tee_time: i === 0 ? startHHMM : "", members })));
119	    clearSel();
120	    setDirty(true);
121	  }
122	  function generate() {
123	    if (teams.some((t) => t.members.length > 0)) setConfirmGen(true);
124	    else doGenerate();
125	  }
126	
127	  async function autoHandicaps() {
128	    if (calcBusy) return;
129	    setCalcBusy(true);
130	    setError(null);
131	    try {
132	      const res = await fetch(`/api/v2/orgs/${orgId}/events/${eventId}/contests/${contestId}/teams/handicaps`, {
133	        method: "POST",
134	        headers: { "Content-Type": "application/json" },
135	        body: JSON.stringify({ teams: teams.map((t) => ({ key: t.key, members: t.members })) }),
136	      });
137	      const d = await res.json().catch(() => ({}));
138	      if (!res.ok) { setError(d.error || "Could not calculate handicaps"); return; }
139	      const handicaps: Record<string, number> = d.handicaps || {};
140	      // Apply directly (not via mutate, which would wipe the breakdowns we set next).
141	      setTeams((prev) => prev.map((t) => (handicaps[t.key] != null ? { ...t, handicap: handicaps[t.key] } : t)));
142	      setDirty(true);
143	      setBreakdowns(d.breakdowns || {});
144	      setCalcTeeName(d.tee_name || null);
145	      setMissingCount((d.missing || []).length);
146	    } finally {
147	      setCalcBusy(false);
148	    }
149	  }
150	
151	  function addTeam() {
152	    // With players selected, create the team AND drop them in (removing them from
153	    // any team they were on) in one step.
154	    const ids = [...selected];
155	    mutate((d) => [
156	      ...d.map((t) => ({ ...t, members: t.members.filter((m) => !selected.has(m)) })),
157	      { key: nextKey(), name: "", handicap: null, tee_time: d.length === 0 ? startHHMM : "", members: ids },
158	    ]);
159	    clearSel();
160	  }
161	  function removeTeam(key: string) {
162	    mutate((d) => d.filter((t) => t.key !== key)); // members fall back to the pool
163	  }
164	  function placeSelected(teamKey: string) {
165	    if (selected.size === 0) return;
166	    const ids = selected;
167	    mutate((d) => d.map((t) => ({ ...t, members: t.members.filter((m) => !ids.has(m)) })).map((t) => (t.key === teamKey ? { ...t, members: [...t.members, ...ids] } : t)));
168	    clearSel();
169	  }
170	  function removeMember(uid: string) {
171	    mutate((d) => d.map((t) => ({ ...t, members: t.members.filter((m) => m !== uid) })));
172	    setSelected((prev) => { if (!prev.has(uid)) return prev; const n = new Set(prev); n.delete(uid); return n; });
173	  }
174	  function setHandicap(key: string, delta: number) {
175	    mutate((d) => d.map((t) => (t.key === key ? { ...t, handicap: Math.max(0, Math.min(54, (t.handicap ?? 0) + delta)) } : t)));
176	  }
177	  function setField(key: string, patch: Partial<LocalTeam>) {
178	    mutate((d) => d.map((t) => (t.key === key ? { ...t, ...patch } : t)));
179	  }
180	
181	  async function save() {
182	    if (saving) return;
183	    setSaving(true);
184	    setError(null);
185	    const res = await fetch(`/api/v2/orgs/${orgId}/events/${eventId}/contests/${contestId}/teams`, {
186	      method: "PUT",
187	      headers: { "Content-Type": "application/json" },
188	      body: JSON.stringify({
189	        teams: teams.map((t) => ({ name: t.name || null, team_handicap: t.handicap, tee_time: t.tee_time || null, members: t.members })),
190	      }),
191	    });
192	    setSaving(false);
193	    if (!res.ok) {
194	      setError((await res.json().catch(() => ({}))).error || "Could not save");
195	      return;
196	    }
197	    const { teams: saved } = (await res.json()) as { teams: TeamData[] };
198	    keySeq.current = 0;
199	    setTeams(saved.map((t) => ({ key: nextKey(), name: t.name || "", handicap: t.team_handicap, tee_time: t.tee_time ? t.tee_time.slice(0, 5) : "", members: [...t.members] })));
200	    setDirty(false);
201	  }
202	
203	  return (
204	    <div>
205	      <div className={styles.teamsControls}>
206	        <div className={styles.pillRow} role="group" aria-label="Team size">
207	          {SIZES.map((s) => (
208	            <button key={s} type="button" className={styles.pill} data-on={teamSize === s || undefined} onClick={() => setTeamSize(s)}>
209	              {s}-man
210	            </button>
211	          ))}
212	        </div>
213	        <button type="button" className={styles.genBtn} onClick={generate}>
214	          <svg width="16" height="16" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" viewBox="0 0 24 24" aria-hidden>
215	            <path d="M16 3h5v5M4 20L21 3M21 16v5h-5M15 15l6 6M4 4l5 5" />
216	          </svg>
217	          Generate teams
218	        </button>
219	        <button type="button" className={styles.calcBtn} onClick={autoHandicaps} disabled={calcBusy || teams.length === 0}>
220	          {calcBusy ? "Calculating…" : "Auto handicaps"}
221	        </button>
222	      </div>
223	      {missingCount > 0 && (
224	        <p className={styles.teamsHint}>
225	          {missingCount} player{missingCount === 1 ? "" : "s"} had no handicap on file (counted as 0). Adjust manually if needed.
226	        </p>
227	      )}
228	
229	      {hasSel && (
230	        <p className={styles.teamsHint}>
231	          <strong>{selected.size}</strong> selected. Tap a team&apos;s <strong>+ Add</strong>, or <strong>New team</strong>.{" "}
232	          <button type="button" className={styles.linkAction} onClick={clearSel}>Clear</button>
233	        </p>
234	      )}
235	
236	      {/* Unassigned pool */}
237	      <div className={styles.section}>
238	        <p className={styles.sectionLabel}>Unassigned ({unassigned.length})</p>
239	        {unassigned.length === 0 ? (
240	          <p className={styles.dnsHint}>Everyone&apos;s on a team.</p>
241	        ) : (
242	          <div className={styles.contestRoster}>
243	            {unassigned.map((p) => (
244	              <button
245	                key={p.user_id}
246	                type="button"
247	                className={styles.rosterChip}
248	                data-selected={selected.has(p.user_id) || undefined}
249	                onClick={() => toggleSel(p.user_id)}
250	              >
251	                {p.avatar_url ? <img src={p.avatar_url} alt="" className={styles.rosterChipAvatar} /> : <span className={styles.rosterChipAvatar} data-mono>{name(p.user_id).charAt(0).toUpperCase()}</span>}
252	                {name(p.user_id)}
253	              </button>
254	            ))}
255	          </div>
256	        )}
257	      </div>
258	
259	      {/* Teams */}
260	      <div className={styles.teamList}>
261	        {teams.map((t, i) => (
262	          <div
263	            key={t.key}
264	            className={styles.teamCard}
265	            data-target={hasSel ? "1" : undefined}
266	            onClick={() => hasSel && placeSelected(t.key)}
267	          >
268	            <div className={styles.teamHead}>
269	              <input
270	                className={styles.teamNameInput}
271	                value={t.name}
272	                placeholder={`Team ${i + 1}`}
273	                onClick={(e) => e.stopPropagation()}
274	                onChange={(e) => setField(t.key, { name: e.target.value })}
275	                maxLength={40}
276	              />
277	              <button type="button" className={styles.teamRemove} aria-label="Remove team" onClick={(e) => { e.stopPropagation(); removeTeam(t.key); }}>
278	                <svg width="16" height="16" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" viewBox="0 0 24 24"><path d="M6 18L18 6M6 6l12 12" /></svg>
279	              </button>
280	            </div>
281	
282	            {hasSel && selectedIds.some((id) => !t.members.includes(id)) && (
283	              <button type="button" className={styles.teamAddHere} onClick={(e) => { e.stopPropagation(); placeSelected(t.key); }}>
284	                + Add {addLabel}
285	              </button>
286	            )}
287	
288	            {t.members.length > 0 && (
289	              <div className={styles.teamMembers}>
290	                {t.members.map((uid) => (
291	                  <button
292	                    key={uid}
293	                    type="button"
294	                    className={styles.rosterChip}
295	                    data-selected={selected.has(uid) || undefined}
296	                    onClick={(e) => { e.stopPropagation(); toggleSel(uid); }}
297	                  >
298	                    {name(uid)}
299	                    <span
300	                      className={styles.chipX}
301	                      role="button"
302	                      aria-label={`Remove ${name(uid)}`}
303	                      onClick={(e) => { e.stopPropagation(); removeMember(uid); }}
304	                    >
305	                      <svg width="12" height="12" fill="none" stroke="currentColor" strokeWidth={2.4} strokeLinecap="round" viewBox="0 0 24 24"><path d="M6 18L18 6M6 6l12 12" /></svg>
306	                    </span>
307	                  </button>
308	                ))}
309	              </div>
310	            )}
311	
312	            <div className={styles.teamMeta} onClick={(e) => e.stopPropagation()}>
313	              <div className={styles.teamStepper}>
