const a=createClient(process.env.NEXT_PUBLIC_SUPABASE_URL,process.env.SUPABASE_SERVICE_ROLE_KEY,{auth:{persistSession:false}});
const cid="712e52f0-3d05-4357-906a-2f97cd4c00ba";
const {data:parts}=await a.from("v2_contest_participants").select("user_id").eq("contest_id",cid);
const ids=parts.map(p=>p.user_id);
const {data:h}=await a.from("v2_player_handicaps").select("user_id,handicap_index").in("user_id",ids);
const hm=new Map(h.map(x=>[x.user_id,Number(x.handicap_index)]));
const players=ids.map(id=>({id,hi:hm.get(id)??Infinity})).sort((x,y)=>x.hi-y.hi);
const teamSize=4, numTeams=Math.max(1,Math.ceil(players.length/teamSize));
const teams=Array.from({length:numTeams},()=>[]);
players.forEach((p,rank)=>{const tier=Math.floor(rank/numTeams),pos=rank%numTeams;const ti=tier%2===0?pos:numTeams-1-pos;teams[ti].push(p);});
console.log("Players:",players.length,"Teams:",numTeams);
const sums=teams.map(t=>t.reduce((s,p)=>s+(isFinite(p.hi)?p.hi:0),0));
teams.forEach((t,i)=>console.log(`Team ${i+1}: [${t.map(p=>p.hi.toFixed(1)).join(", ")}]  sum=${sums[i].toFixed(1)}`));
console.log("Team-sum spread:",Math.min(...sums).toFixed(1),"to",Math.max(...sums).toFixed(1));
});'

