1	"use client";
2	
3	import { useMemo, useState } from "react";
4	import Modal from "@/app/new/_components/Modal";
5	import styles from "@/app/new/new.module.css";
6	
7	export interface ScoreHole { hole_number: number; par: number; handicap_index: number }
8	export interface ScoreTeam { id: string; name: string | null; team_handicap: number | null; members: string[] }
9	interface ScoreRow { team_id: string; hole_number: number; strokes: number }
10	interface ObsRow { user_id: string; hole_number: number; metric: string; value: number }
11	interface PlayerObs { on_green: boolean; holed_out: boolean }
12	
13	/**
14	 * Scramble scoring — review-first (#209). A list of groups with their round
15	 * summary; tapping a group expands an inline scorecard. Tapping a hole opens a
16	 * floating editor (team score stepper + each player's Green / Putt toggle) with
17	 * prev/next arrows. Optimistic: one hole saved per PUT in the background.
18	 */
19	export default function ScoringManager({
20	  orgId,
21	  eventId,
22	  contestId,
23	  holes,
24	  teams,
25	  initialScores,
26	  initialObs,
27	  names,
28	}: {
29	  orgId: string;
30	  eventId: string;
31	  contestId: string;
32	  holes: ScoreHole[];
33	  teams: ScoreTeam[];
34	  initialScores: ScoreRow[];
35	  initialObs: ObsRow[];
36	  names: Record<string, string>;
37	}) {
38	  const [expanded, setExpanded] = useState<Set<string>>(new Set());
39	  const [scores, setScores] = useState<Record<string, Record<number, number>>>(() => {
40	    const m: Record<string, Record<number, number>> = {};
41	    for (const s of initialScores) (m[s.team_id] ||= {})[s.hole_number] = s.strokes;
42	    return m;
43	  });
44	  const [obs, setObs] = useState<Record<string, PlayerObs>>(() => {
45	    const m: Record<string, PlayerObs> = {};
46	    for (const o of initialObs) {
47	      const k = `${o.user_id}|${o.hole_number}`;
48	      const cur = m[k] || { on_green: false, holed_out: false };
49	      if (o.metric === "on_green") cur.on_green = o.value === 1;
50	      if (o.metric === "holed_out") cur.holed_out = o.value === 1;
51	      m[k] = cur;
52	    }
53	    return m;
54	  });
55	  const [editTeamId, setEditTeamId] = useState<string | null>(null);
56	  const [editHole, setEditHole] = useState<number | null>(null);
57	  const [wScore, setWScore] = useState<number | "">("");
58	  const [wPlayers, setWPlayers] = useState<Record<string, PlayerObs>>({});
59	
60	  const lowestHcp = teams.length ? Math.min(...teams.map((t) => t.team_handicap ?? 0)) : 0;
61	  const holeByNum = useMemo(() => new Map(holes.map((h) => [h.hole_number, h])), [holes]);
62	  const holeNums = useMemo(() => holes.map((h) => h.hole_number).sort((a, b) => a - b), [holes]);
63	  const editTeam = teams.find((t) => t.id === editTeamId) || null;
64	
65	  function toggleExpand(id: string) {
66	    setExpanded((prev) => { const n = new Set(prev); if (n.has(id)) n.delete(id); else n.add(id); return n; });
67	  }
68	
69	  function totals(t: ScoreTeam) {
70	    const sc = scores[t.id] || {};
71	    const played = holes.filter((h) => sc[h.hole_number] != null);
72	    const total = played.reduce((s, h) => s + sc[h.hole_number], 0);
73	    const parPlayed = played.reduce((s, h) => s + h.par, 0);
74	    const adj = Math.max(0, (t.team_handicap ?? 0) - lowestHcp);
75	    return {
76	      thru: played.length,
77	      total: played.length ? total : null,
78	      vsPar: played.length ? total - parPlayed : null,
79	      net: played.length ? total - adj : null,
80	    };
81	  }
82	
83	
84	  function openHole(teamId: string, n: number) {
85	    const t = teams.find((x) => x.id === teamId);
86	    if (!t) return;
87	    setWScore(scores[teamId]?.[n] ?? "");
88	    const pl: Record<string, PlayerObs> = {};
89	    for (const uid of t.members) pl[uid] = { ...(obs[`${uid}|${n}`] || { on_green: false, holed_out: false }) };
90	    setWPlayers(pl);
91	    setEditTeamId(teamId);
92	    setEditHole(n);
93	  }
94	
95	  // Optimistic: commit the hole to local state immediately, save in the background.
96	  function commitHole(n: number) {
97	    const t = teams.find((x) => x.id === editTeamId);
98	    if (!t) return;
99	    const tid = t.id;
100	    const members = t.members;
101	    const strokes = wScore === "" ? null : Number(wScore);
102	    const players = wPlayers;
103	
104	    setScores((prev) => {
105	      const row = { ...(prev[tid] || {}) };
106	      if (strokes == null) delete row[n]; else row[n] = strokes;
107	      return { ...prev, [tid]: row };
108	    });
109	    setObs((prev) => {
110	      const next = { ...prev };
111	      for (const uid of members) next[`${uid}|${n}`] = { ...(players[uid] || { on_green: false, holed_out: false }) };
112	      return next;
113	    });
114	
115	    fetch(`/api/v2/orgs/${orgId}/events/${eventId}/contests/${contestId}/scores`, {
116	      method: "PUT",
117	      headers: { "Content-Type": "application/json" },
118	      body: JSON.stringify({
119	        team_id: tid,
120	        hole_number: n,
121	        strokes,
122	        observations: members.map((uid) => ({ user_id: uid, on_green: players[uid]?.on_green, holed_out: players[uid]?.holed_out })),
123	      }),
124	    }).catch(() => {});
125	  }
126	
127	  function gotoHole(n: number) {
128	    if (editHole != null) commitHole(editHole);
129	    if (editTeamId) openHole(editTeamId, n);
130	  }
131	  function closeEditor() {
132	    if (editHole != null) commitHole(editHole);
133	    setEditHole(null);
134	    setEditTeamId(null);
135	  }
136	
137	  const editPar = editHole != null ? holeByNum.get(editHole)?.par ?? 4 : 4;
138	  function incScore(d: number) {
139	    setWScore((v) => (v === "" ? editPar : Math.max(1, Math.min(20, v + d))));
140	  }
141	  function toggleGreen(uid: string) {
142	    setWPlayers((p) => ({ ...p, [uid]: { on_green: !p[uid]?.on_green, holed_out: p[uid]?.holed_out ?? false } }));
143	  }
144	  function toggleHoled(uid: string) {
145	    setWPlayers((p) => {
146	      const turningOn = !p[uid]?.holed_out;
147	      const next: Record<string, PlayerObs> = {};
148	      for (const m of editTeam?.members || []) next[m] = { on_green: p[m]?.on_green ?? false, holed_out: m === uid ? turningOn : false };
149	      return next;
150	    });
151	  }
