"use client";

import { useState } from "react";
import Modal from "@/app/new/_components/Modal";
import ConfirmModal from "@/app/new/_components/ConfirmModal";
import styles from "@/app/new/new.module.css";

export interface OptItem {
  id: string;
  name: string;
  amount_cents: number;
  source_type: string;
}
export interface OptionData {
  id: string;
  name: string;
  description: string | null;
  price_cents: number;
  items: OptItem[];
}

function dollars(cents: number): string {
  return `$${(cents / 100).toLocaleString("en-US", { minimumFractionDigits: cents % 100 === 0 ? 0 : 2, maximumFractionDigits: 2 })}`;
}
const priceOf = (items: OptItem[]) => items.reduce((s, i) => s + i.amount_cents, 0);

/**
 * Build opt-in options and bundle cost items (contests/costs) into each. An option's
 * price is the sum of its bundled items (derived). Reconciling an item into an option
 * moves it out of "available" (it leaves Trip Cost automatically on the server).
 */
export default function OptionsManager({
  slug,
  orgId,
  eventId,
  initialOptions,
  initialAvailable,
}: {
  slug: string;
  orgId: string;
  eventId: string;
  initialOptions: OptionData[];
  initialAvailable: OptItem[];
}) {
  const optionsBase = `/api/v2/orgs/${orgId}/events/${eventId}/options`;
  const costBase = `/api/v2/orgs/${orgId}/events/${eventId}/cost-items`;
  void slug;

  const [options, setOptions] = useState<OptionData[]>(initialOptions);
  const [available, setAvailable] = useState<OptItem[]>(initialAvailable);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [formOpen, setFormOpen] = useState(false);
  const [editing, setEditing] = useState<OptionData | null>(null);
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [addingTo, setAddingTo] = useState<OptionData | null>(null);
  const [confirmDel, setConfirmDel] = useState<OptionData | null>(null);

  function openCreate() { setEditing(null); setName(""); setDescription(""); setError(null); setFormOpen(true); }
  function openEdit(o: OptionData) { setEditing(o); setName(o.name); setDescription(o.description || ""); setError(null); setFormOpen(true); }

  async function submitOption(e: React.FormEvent) {
    e.preventDefault();
    if (busy) return;
    if (!name.trim()) { setError("Name is required"); return; }
    setBusy(true); setError(null);
    try {
      if (editing) {
        const res = await fetch(`${optionsBase}/${editing.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ name: name.trim(), description }) });
        if (!res.ok) { setError((await res.json().catch(() => ({}))).error || "Could not save"); return; }
        const { option } = await res.json();
        setOptions((prev) => prev.map((o) => (o.id === editing.id ? { ...o, name: option.name, description: option.description } : o)));
      } else {
        const res = await fetch(optionsBase, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ name: name.trim(), description }) });
        if (!res.ok) { setError((await res.json().catch(() => ({}))).error || "Could not create"); return; }
        const { option } = await res.json();
        setOptions((prev) => [...prev, { id: option.id, name: option.name, description: option.description, price_cents: 0, items: [] }]);
      }
      setFormOpen(false);
    } finally {
      setBusy(false);
    }
  }

  async function deleteOption(o: OptionData) {
    setBusy(true);
    try {
      const res = await fetch(`${optionsBase}/${o.id}`, { method: "DELETE" });
      if (!res.ok) { setError((await res.json().catch(() => ({}))).error || "Could not delete"); return; }
      // Its bundled items become available again.
      setAvailable((prev) => [...prev, ...o.items].sort((a, b) => a.name.localeCompare(b.name)));
      setOptions((prev) => prev.filter((x) => x.id !== o.id));
      setConfirmDel(null);
    } finally {
      setBusy(false);
    }
  }

  async function setItemOption(item: OptItem, optionId: string | null) {
    const res = await fetch(`${costBase}/${item.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ linked_option_id: optionId }) });
    if (!res.ok) { setError((await res.json().catch(() => ({}))).error || "Could not update"); return false; }
    return true;
  }

  async function linkItem(option: OptionData, item: OptItem) {
    if (busy) return;
    setBusy(true); setError(null);
    try {
      if (!(await setItemOption(item, option.id))) return;
      setAvailable((prev) => prev.filter((i) => i.id !== item.id));
      setOptions((prev) => prev.map((o) => {
        if (o.id !== option.id) return o;
        const items = [...o.items, item];
        return { ...o, items, price_cents: priceOf(items) };
      }));
    } finally {
      setBusy(false);
    }
  }

  async function unlinkItem(option: OptionData, item: OptItem) {
    if (busy) return;
    setBusy(true); setError(null);
    try {
      if (!(await setItemOption(item, null))) return;
      setOptions((prev) => prev.map((o) => {
        if (o.id !== option.id) return o;
        const items = o.items.filter((i) => i.id !== item.id);
        return { ...o, items, price_cents: priceOf(items) };
      }));
      setAvailable((prev) => [...prev, item].sort((a, b) => a.name.localeCompare(b.name)));
    } finally {
      setBusy(false);
    }
  }

  // Keep the add-picker's option reference fresh as items move.
  const addingToLive = addingTo ? options.find((o) => o.id === addingTo.id) || null : null;

  return (
    <div>
      {error && <p className={styles.formError} style={{ marginTop: 12 }}>{error}</p>}

      <div className={styles.titleRow} style={{ marginTop: 18 }}>
        <p className={styles.sectionLabel} style={{ marginBottom: 0 }}>Options ({options.length})</p>
        <button type="button" className={styles.circleAdd} aria-label="Add option" onClick={openCreate}>
          <svg width="15" height="15" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 5v14M5 12h14" /></svg>
        </button>
      </div>

      {options.length === 0 ? (
        <p className={styles.dnsHint} style={{ marginTop: 10 }}>No options yet. Add one, then bundle the contests or costs it covers.</p>
      ) : (
        <div className={styles.finGroups} style={{ marginTop: 10 }}>
          {options.map((o) => (
            <div key={o.id} className={styles.finGroup}>
              <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", gap: 10 }}>
                <p className={styles.finGroupHead} style={{ margin: 0 }}>{o.name}</p>
                <span className={styles.finRowAmount}>{dollars(o.price_cents)}</span>
              </div>
              {o.description && <p className={styles.roundFormHint} style={{ margin: "2px 0 8px" }}>{o.description}</p>}

              {o.items.length === 0 ? (
                <p className={styles.dnsHint} style={{ marginTop: 4 }}>Nothing bundled yet. A $0 option is a free opt-in.</p>
              ) : (
                <div className={styles.memberList} style={{ marginTop: 4 }}>
                  {o.items.map((it) => (
                    <div key={it.id} className={styles.finRow}>
                      <div className={styles.finRowMain}>
                        <span className={styles.finRowName}>{it.name}</span>
                      </div>
                      <span className={styles.finRowAmount}>{dollars(it.amount_cents)}</span>
                      <button type="button" className={styles.removeBtn} onClick={() => unlinkItem(o, it)} disabled={busy} style={{ marginLeft: 8 }}>Remove</button>
                    </div>
                  ))}
                </div>
              )}

              <div style={{ display: "flex", gap: 8, marginTop: 10, flexWrap: "wrap" }}>
                <button type="button" className={styles.createBtnGhost} onClick={() => setAddingTo(o)} disabled={available.length === 0}>
                  Add cost{available.length === 0 ? " (none free)" : ""}
                </button>
                <button type="button" className={styles.createBtnGhost} onClick={() => openEdit(o)}>Edit</button>
                <button type="button" className={styles.deleteBtn} onClick={() => setConfirmDel(o)} disabled={busy}>Delete</button>
              </div>
            </div>
          ))}
        </div>
      )}

      {available.length > 0 && (
        <div className={styles.section} style={{ marginTop: 22 }}>
          <p className={styles.sectionLabel}>Not in Trip Cost, not in an option ({available.length})</p>
          <p className={styles.roundFormHint} style={{ marginTop: -2, marginBottom: 8 }}>
            These costs aren&apos;t charged to anyone yet. Bundle each into an option (or mark it Trip Cost on the Financials screen).
          </p>
          <div className={styles.memberList}>
            {available.map((it) => (
              <div key={it.id} className={styles.finRow}>
                <div className={styles.finRowMain}><span className={styles.finRowName}>{it.name}</span></div>
                <span className={styles.finRowAmount}>{dollars(it.amount_cents)}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Create / edit option */}
      <Modal open={formOpen} title={editing ? "Edit option" : "Add option"} onClose={() => (busy ? undefined : setFormOpen(false))}>
        <form className={styles.form} onSubmit={submitOption}>
          <div className={styles.field}>
            <label className={styles.label}>Name</label>
            <input className={styles.input} value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. Closest to the Pin" maxLength={120} autoFocus />
          </div>
          <div className={styles.field}>
            <label className={styles.label}>Description <span className={styles.optional}>(optional)</span></label>
            <textarea className={styles.textarea} value={description} onChange={(e) => setDescription(e.target.value)} placeholder="What members are opting into" maxLength={300} />
          </div>
          {error && <p className={styles.formError}>{error}</p>}
          <button type="submit" className={styles.createBtn} disabled={busy} style={{ opacity: busy ? 0.6 : 1 }}>
            {busy ? "Saving…" : editing ? "Save option" : "Add option"}
          </button>
        </form>
      </Modal>

      {/* Add a cost to an option */}
      <Modal open={!!addingTo} title={addingTo ? `Add costs to ${addingTo.name}` : ""} onClose={() => (busy ? undefined : setAddingTo(null))}>
        {available.length === 0 ? (
          <p className={styles.dnsHint} style={{ marginTop: 0 }}>Nothing available. Create a contest with a buy-in, or add a manual cost on the Financials screen first.</p>
        ) : (
          <div className={styles.memberList}>
            {available.map((it) => (
              <button
                key={it.id}
                type="button"
                className={styles.memberRowBtn}
                disabled={busy}
                onClick={() => addingToLive && linkItem(addingToLive, it)}
              >
                <div className={styles.memberMeta} style={{ minWidth: 0 }}>
                  <div className={styles.memberName}>{it.name}</div>
                </div>
                <span className={styles.finRowAmount}>{dollars(it.amount_cents)}</span>
