export default async function HomeModules({
  orgId,
  eventId,
  userId,
  slug,
  eventName,
  storeUrl,
  storeLabel,
  storeEnabled,
  nameDisplay,
  articlesVisible,
}: {
  orgId: string;
  eventId: string;
  userId: string;
  slug: string;
  eventName: string;
  storeUrl: string | null;
  storeLabel: string | null;
  storeEnabled: boolean;
  nameDisplay: NameMode;
  articlesVisible: boolean;
}) {
  const supabase = await v2ServerClient();

  const now = await v2Now();
  const nowIso = now.toISOString();

  // Birthdays + article + RSVP + attending count + ads + activity, in parallel.
  const [membersRes, articleRes, myRsvpRes, goingRes, attendingRes, adsRes, activityRes, orgSysRes] =
    await Promise.all([
    supabase
      .from("v2_memberships")
      .select("user_id, v2_profiles(id, display_name, first_name, last_name, birthdate, avatar_url)")
      .eq("org_id", orgId)
      .eq("status", "active")
      .is("archived_at", null),
    // Latest published article for the org (event-specific scoping comes later).
    supabase
      .from("v2_articles")
      .select(
        "id, title, publish_at, image_url, content, image_focal_x, image_focal_y, author:v2_profiles!v2_articles_author_id_fkey(display_name, first_name, last_name, avatar_url)",
      )
      .eq("org_id", orgId)
      .not("publish_at", "is", null)
      .lte("publish_at", nowIso)
      .order("pinned_at", { ascending: false, nullsFirst: false })
      .order("publish_at", { ascending: false })
      .limit(1)
      .maybeSingle(),
    supabase
      .from("v2_event_participants")
      .select("likelihood")
      .eq("event_id", eventId)
      .eq("user_id", userId)
      .maybeSingle(),
    supabase
      .from("v2_event_participants")
      .select("id", { count: "exact", head: true })
      .eq("event_id", eventId),
    supabase
      .from("v2_event_participants")
      .select("id", { count: "exact", head: true })
      .eq("event_id", eventId)
      .eq("on_roster", true),
    supabase
      .from("v2_ads")
      .select("id, image_url, alt_text")
      .eq("org_id", orgId)
      .eq("active", true),
    supabase
      .from("v2_activity")
      .select("id, kind, title, subtitle, image_url, link, created_at, ref_id, metadata, actor:v2_profiles(display_name, first_name, last_name, avatar_url)")
      .eq("org_id", orgId)
      .order("created_at", { ascending: false })
      .limit(15),
    supabase
      .from("v2_organizations")
      .select("system_name, system_avatar_url")
      .eq("id", orgId)
      .maybeSingle(),
  ]);

  const myLikelihood = (myRsvpRes.data?.likelihood as Likelihood | undefined) ?? null;
  const responseCount = goingRes.count ?? 0;
  const attendingCount = attendingRes.count ?? 0;
  const ads = (adsRes.data as Ad[] | null) ?? [];
  const activity = ((activityRes.data as unknown as (Omit<ActivityRow, "actor"> & {
    actor: ActivityRow["actor"] | ActivityRow["actor"][];
  })[]) ?? []).map((a) => ({
    ...a,
    actor: Array.isArray(a.actor) ? a.actor[0] ?? null : a.actor,
  })) as ActivityRow[];

  const orgSys = (orgSysRes.data as { system_name: string | null; system_avatar_url: string | null } | null) ?? null;
  const systemName = orgSys?.system_name?.trim() || "System";
  const systemAvatar = orgSys?.system_avatar_url ?? null;

  const birthdays = birthdaysToday(
    (membersRes.data as unknown as { v2_profiles: MemberProfile | null }[]) || [],
    nameDisplay,
    now,
  );

  // Featured article (null until 00185 is applied / an article is published).
  const row = articleRes.error ? null : (articleRes.data as ArticleRow | null);
  const rowAuthor = row ? (Array.isArray(row.author) ? row.author[0] : row.author) : null;
  const article: FeaturedArticle | null = row
    ? {
        id: row.id,
        title: row.title,
        publishAt: row.publish_at,
        imageUrl: row.image_url,
        preview: stripMarkdown(row.content || "") || null,
        focalX: row.image_focal_x ?? 50,
        focalY: row.image_focal_y ?? 50,
        authorName: rowAuthor ? pickName(rowAuthor, nameDisplay) : null,
        authorAvatar: rowAuthor?.avatar_url ?? null,
      }
    : null;

  return (
    <>
      <BirthdayBanner birthdays={birthdays} slug={slug} />
      {articlesVisible && article && <ArticleModule article={article} slug={slug} />}
      <RsvpModule
        eventId={eventId}
        eventName={eventName}
        initialLikelihood={myLikelihood}
        initialResponseCount={responseCount}
        initialAttendingCount={attendingCount}
      />
      <StoreModule storeUrl={storeEnabled ? storeUrl : null} storeLabel={storeLabel} />
      <ActivityFeed initialItems={activity} orgId={orgId} systemName={systemName} systemAvatar={systemAvatar} />
      <AdCarousel ads={ads} />

