export interface OptItem {
  id: string;
  name: string;
  amount_cents: number;
  source_type: string;
  group_key: string;
  group_label: string;
  sort_order: number;
}

/** Group items by contest/category and order them like the Financials screen:
 *  contest groups first, then category groups; sort_order within each. */
function groupItems(items: OptItem[]): { key: string; label: string; list: OptItem[] }[] {
  const byKey = new Map<string, { label: string; list: OptItem[] }>();
  for (const i of items) {
    const g = byKey.get(i.group_key) || byKey.set(i.group_key, { label: i.group_label, list: [] }).get(i.group_key)!;
