toolUseResult.originalFile:
/**
 * v2 Options + money derivation (#216, epic #214).
 *
 * An Option is the member-facing, all-or-nothing opt-in. Its PRICE is derived from
 * the cost_items linked to it (`v2_cost_items.linked_option_id`) — never stored, so
 * editing a cost_item re-prices automatically. An Option bundles the CONTESTS whose
 * buy-in cost_items are linked to it; selecting it enrolls into all of them (#216
 * slice 2). Trip Cost is the one special derived option = SUM(included_in_trip_cost).
 */

import type { SupabaseClient } from "@supabase/supabase-js";

export const OPTION_SELECT =
  "id, org_id, event_id, group_id, name, description, option_type, choices, is_required, max_total, icon, depends_on_option_id, sort_order, created_at, updated_at";

export type OptionType = "checkbox" | "select" | "multi_select" | "quantity" | "text" | "number" | "trip_cost";

/** One choice on a select/multi_select/quantity option. `value` is a slug of `label`.
 *  Real price derives from linked cost_items; `cost` is only a display fallback. */
export interface OptionChoice {
  label: string;
  value: string;
  cost?: number | null;
  contest_id?: string | null;
}

export interface Option {
  id: string;
  org_id: string;
  event_id: string;
  group_id: string | null;
  name: string;
  description: string | null;
  option_type: OptionType;
  choices: OptionChoice[] | null;
  is_required: boolean;
  max_total: number | null;
  icon: string | null;
  depends_on_option_id: string | null;
  sort_order: number;
  created_at: string;
  updated_at: string;
}

export const OPTION_GROUP_SELECT = "id, org_id, event_id, name, description, icon, sort_order, created_at, updated_at";

export interface OptionGroup {
  id: string;
  org_id: string;
  event_id: string;
  name: string;
  description: string | null;
  icon: string | null;
  sort_order: number;
  created_at: string;
  updated_at: string;
}

/** The 7 option types + whether each takes choices / a cost. */
export const OPTION_TYPES: { type: OptionType; label: string; hasChoices: boolean; priced: boolean }[] = [
  { type: "checkbox", label: "Checkbox (yes/no)", hasChoices: false, priced: true },
  { type: "select", label: "Select one", hasChoices: true, priced: true },
  { type: "multi_select", label: "Select many", hasChoices: true, priced: true },
  { type: "quantity", label: "Quantity", hasChoices: true, priced: true },
  { type: "text", label: "Text", hasChoices: false, priced: false },
  { type: "number", label: "Number", hasChoices: false, priced: false },
  { type: "trip_cost", label: "Trip Cost (auto)", hasChoices: false, priced: true },
];

/** label → url-safe choice value (stable id stored in selections + cost links). */
export function slugifyChoice(label: string): string {
  return label.trim().toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "").slice(0, 60) || "choice";
}

/** Derived price (cents) per option = SUM of the cost_items linked to it. */
export async function loadOptionPrices(admin: SupabaseClient, optionIds: string[]): Promise<Map<string, number>> {
  const out = new Map<string, number>();
  if (!optionIds.length) return out;
  const { data } = await admin
    .from("v2_cost_items")
    .select("linked_option_id, amount_cents")
    .in("linked_option_id", optionIds);
  for (const r of data || []) {
    const oid = r.linked_option_id as string | null;
    if (!oid) continue;
    out.set(oid, (out.get(oid) || 0) + ((r.amount_cents as number) || 0));
  }
  return out;
}

/** Trip Cost (cents) for an event = SUM of cost_items marked included_in_trip_cost. */
export async function tripCostCents(admin: SupabaseClient, eventId: string): Promise<number> {
  const { data } = await admin
    .from("v2_cost_items")
    .select("amount_cents")
    .eq("event_id", eventId)
    .eq("included_in_trip_cost", true);
  return (data || []).reduce((s, r) => s + ((r.amount_cents as number) || 0), 0);
}

/** The contest ids an option bundles (its linked cost_items' source contests/side games). */
export async function optionContestIds(admin: SupabaseClient, optionId: string): Promise<string[]> {
  const { data } = await admin
    .from("v2_cost_items")
    .select("source_id")
    .eq("linked_option_id", optionId)
    .in("source_type", ["contest", "side_game"]);
  return [...new Set((data || []).map((r) => r.source_id as string | null).filter((x): x is string => !!x))];
}

/**
 * All-or-nothing: selecting an option enrolls the member into every contest it bundles;
 * deselecting removes them from all of them (#216). Idempotent. Options are the only
 * enrollment path for opt-in contests, so removal is safe (no cross-option sharing).
 */
export async function syncOptionContestEnrollment(
  admin: SupabaseClient,
  optionId: string,
  userId: string,
  selected: boolean,
): Promise<void> {
  const contestIds = await optionContestIds(admin, optionId);
  if (contestIds.length === 0) return;
  if (selected) {
    const rows = contestIds.map((contest_id) => ({ contest_id, user_id: userId }));
    await admin.from("v2_contest_participants").upsert(rows, { onConflict: "contest_id,user_id", ignoreDuplicates: true });
  } else {
    await admin.from("v2_contest_participants").delete().eq("user_id", userId).in("contest_id", contestIds);
  }
}

import { NextResponse } from "next/server";
import { v2GetUser, v2AdminClient } from "@/lib/v2/supabase";
import { isOrgAdmin, isOrgMember } from "@/lib/v2/orgs";
import { OPTION_SELECT, loadOptionPrices, type Option } from "@/lib/v2/options";

type Params = Promise<{ id: string; eventId: string }>;

/**
 * Event options (#216). GET returns each option with its DERIVED price (sum of its
 * linked cost_items) and the cost_items it bundles. Any member may read; admins write.
 */
export async function GET(request: Request, { params }: { params: Params }) {
  const { userId } = await v2GetUser(request);
  if (!userId) return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
  const { id: orgId, eventId } = await params;

  const admin = v2AdminClient();
  if (!(await isOrgMember(admin, userId, orgId))) return NextResponse.json({ error: "Not a member" }, { status: 403 });

  const { data: optRows } = await admin
    .from("v2_options").select(OPTION_SELECT).eq("event_id", eventId).order("sort_order");
  const options = (optRows || []) as Option[];
  const ids = options.map((o) => o.id);
  const prices = await loadOptionPrices(admin, ids);

  const { data: itemRows } = ids.length
    ? await admin.from("v2_cost_items").select("id, name, amount_cents, source_type, source_id, linked_option_id").in("linked_option_id", ids)
    : { data: [] as { id: string; name: string; amount_cents: number; source_type: string; source_id: string | null; linked_option_id: string | null }[] };
  const itemsByOption = new Map<string, typeof itemRows>();
  for (const it of itemRows || []) {
    const oid = it.linked_option_id as string;
    (itemsByOption.get(oid) || itemsByOption.set(oid, []).get(oid)!).push(it);
  }

  return NextResponse.json({
    options: options.map((o) => ({ ...o, price_cents: prices.get(o.id) || 0, items: itemsByOption.get(o.id) || [] })),
  });
}

/** Create an option (#216). Admins only. */
export async function POST(request: Request, { params }: { params: Params }) {
  const { userId } = await v2GetUser(request);
  if (!userId) return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
  const { id: orgId, eventId } = await params;

  const admin = v2AdminClient();
  if (!(await isOrgAdmin(admin, userId, orgId))) return NextResponse.json({ error: "Admins only" }, { status: 403 });

  let body: { name?: string; description?: string };
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "Invalid body" }, { status: 400 });
  }
  const name = (body.name || "").trim();
  if (!name) return NextResponse.json({ error: "Name is required" }, { status: 400 });
  if (name.length > 120) return NextResponse.json({ error: "Name is too long" }, { status: 400 });

  const { data: last } = await admin
    .from("v2_options").select("sort_order").eq("event_id", eventId).order("sort_order", { ascending: false }).limit(1).maybeSingle();
  const sort_order = (last?.sort_order ?? -1) + 1;

  const { data, error } = await admin
    .from("v2_options")
    .insert({ org_id: orgId, event_id: eventId, name, description: (body.description || "").trim() || null, sort_order, created_by: userId })
    .select(OPTION_SELECT).single();
  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
  return NextResponse.json({ option: { ...(data as Option), price_cents: 0, items: [] } });
}

