251	          <button type="submit" className={styles.createBtn} disabled={busy} style={{ opacity: busy ? 0.6 : 1 }}>
252	            {busy ? "Saving…" : editing ? "Save option" : "Add option"}
253	          </button>
254	        </form>
255	      </Modal>
256	
257	      {/* Add a cost to an option */}
258	      <Modal open={!!addingTo} title={addingTo ? `Add costs to ${addingTo.name}` : ""} onClose={() => (busy ? undefined : setAddingTo(null))}>
259	        {available.length === 0 ? (
260	          <p className={styles.dnsHint} style={{ marginTop: 0 }}>Nothing available. Create a contest with a buy-in, or add a manual cost on the Financials screen first.</p>
261	        ) : (
262	          <div className={styles.finGroups}>
263	            {availableGroups.map((g) => (
264	              <div key={g.key} className={styles.finGroup}>
265	                <p className={styles.finGroupHead}>{g.label}</p>
266	                <div className={styles.memberList}>
267	                  {g.list.map((it) => (
268	                    <button
269	                      key={it.id}
270	                      type="button"
271	                      className={styles.memberRowBtn}
272	                      disabled={busy}
273	                      onClick={() => addingToLive && linkItem(addingToLive, it)}
274	                    >
275	                      <div className={styles.memberMeta} style={{ minWidth: 0 }}>
276	                        <div className={styles.memberName}>{it.name}</div>
277	                      </div>
278	                      <span className={styles.finRowAmount}>{dollars(it.amount_cents)}</span>
279	                    </button>
280	                  ))}
281	                </div>
282	              </div>
283	            ))}
284	          </div>
285	        )}
286	      </Modal>
287	
288	      <ConfirmModal
289	        open={!!confirmDel}
290	        destructive
291	        title="Delete option?"
292	        message={confirmDel ? `Remove "${confirmDel.name}"? Its ${confirmDel.items.length} bundled cost${confirmDel.items.length === 1 ? "" : "s"} go back to unassigned, and any member selections are cleared.` : ""}
293	        confirmLabel="Delete"
294	        onConfirm={() => confirmDel && deleteOption(confirmDel)}
295	        onCancel={() => (busy ? undefined : setConfirmDel(null))}
296	      />
297	    </div>
298	  );
299	}
