"use client";

import { useState } from "react";
import Modal from "@/app/new/_components/Modal";
import ConfirmModal from "@/app/new/_components/ConfirmModal";
import { OPTION_TYPES, typeHasChoices, type OptionType, type OptionChoice } from "@/lib/v2/options";
import { OPTION_ICON_CATEGORIES } from "@/lib/v2/option-icons";
import styles from "@/app/new/new.module.css";

export interface OptItem {
  id: string;
  name: string;
  amount_cents: number;
  source_type: string;
  group_key: string;
  group_label: string;
  sort_order: number;
}

export interface OptionData {
  id: string;
  name: string;
  description: string | null;
  option_type: OptionType;
  choices: OptionChoice[] | null;
  is_required: boolean;
  max_total: number | null;
  icon: string | null;
  depends_on_option_id: string | null;
  price_cents: number;
  items: OptItem[];
}

function groupItems(items: OptItem[]): { key: string; label: string; list: OptItem[] }[] {
  const byKey = new Map<string, { label: string; list: OptItem[] }>();
  for (const i of items) {
    const g = byKey.get(i.group_key) || byKey.set(i.group_key, { label: i.group_label, list: [] }).get(i.group_key)!;
    g.list.push(i);
  }
  for (const g of byKey.values()) g.list.sort((a, b) => a.sort_order - b.sort_order || a.name.localeCompare(b.name));
  return [...byKey.entries()]
    .sort((a, b) => {
      const ac = a[0].startsWith("contest:") ? 0 : 1;
      const bc = b[0].startsWith("contest:") ? 0 : 1;
      return ac - bc || a[1].label.localeCompare(b[1].label);
    })
    .map(([key, v]) => ({ key, label: v.label, list: v.list }));
}

function dollars(cents: number): string {
  return `$${(cents / 100).toLocaleString("en-US", { minimumFractionDigits: cents % 100 === 0 ? 0 : 2, maximumFractionDigits: 2 })}`;
}
const priceOf = (items: OptItem[]) => items.reduce((s, i) => s + i.amount_cents, 0);
const typeLabel = (t: OptionType) => OPTION_TYPES.find((x) => x.type === t)?.label ?? t;

type ChoiceDraft = { label: string; value: string };

/**
 * Build opt-in options (full type system, #218): checkbox / select / multi-select /
 * quantity / text / number, each with an icon, optional dependency, required flag, and
 * (for choice types) a choices list. Cost items bundle in for pricing (per-choice
 * linking lands in phase B).
 */
export default function OptionsManager({
  slug,
  orgId,
  eventId,
  initialOptions,
  initialAvailable,
}: {
  slug: string;
  orgId: string;
  eventId: string;
  initialOptions: OptionData[];
  initialAvailable: OptItem[];
}) {
  const optionsBase = `/api/v2/orgs/${orgId}/events/${eventId}/options`;
  const costBase = `/api/v2/orgs/${orgId}/events/${eventId}/cost-items`;
  void slug;

  const [options, setOptions] = useState<OptionData[]>(initialOptions);
  const [available, setAvailable] = useState<OptItem[]>(initialAvailable);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [formOpen, setFormOpen] = useState(false);
  const [editing, setEditing] = useState<OptionData | null>(null);
  const [addingTo, setAddingTo] = useState<OptionData | null>(null);
  const [confirmDel, setConfirmDel] = useState<OptionData | null>(null);

  // Form fields
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [optType, setOptType] = useState<OptionType>("checkbox");
  const [choices, setChoices] = useState<ChoiceDraft[]>([]);
  const [maxTotal, setMaxTotal] = useState("");
  const [icon, setIcon] = useState("");
  const [isRequired, setIsRequired] = useState(false);
  const [dependsOn, setDependsOn] = useState("");
  const [iconOpen, setIconOpen] = useState(false);

  function openCreate() {
    setEditing(null); setName(""); setDescription(""); setOptType("checkbox"); setChoices([]);
    setMaxTotal(""); setIcon(""); setIsRequired(false); setDependsOn(""); setIconOpen(false); setError(null); setFormOpen(true);
  }
  function openEdit(o: OptionData) {
    setEditing(o); setName(o.name); setDescription(o.description || ""); setOptType(o.option_type);
    setChoices((o.choices || []).map((c) => ({ label: c.label, value: c.value })));
    setMaxTotal(o.max_total != null ? String(o.max_total) : ""); setIcon(o.icon || ""); setIsRequired(o.is_required);
    setDependsOn(o.depends_on_option_id || ""); setIconOpen(false); setError(null); setFormOpen(true);
  }

  const addChoice = () => setChoices((c) => [...c, { label: "", value: "" }]);
  const updateChoice = (i: number, label: string) => setChoices((c) => c.map((x, j) => (j === i ? { ...x, label } : x)));
  const removeChoice = (i: number) => setChoices((c) => c.filter((_, j) => j !== i));

  async function submitOption(e: React.FormEvent) {
    e.preventDefault();
    if (busy) return;
    if (!name.trim()) { setError("Name is required"); return; }
    setBusy(true); setError(null);
    const payload = {
      name: name.trim(),
      description,
      option_type: optType,
      choices: typeHasChoices(optType) ? choices.filter((c) => c.label.trim()).map((c) => ({ label: c.label.trim(), value: c.value })) : undefined,
      is_required: isRequired,
      max_total: optType === "quantity" && maxTotal.trim() ? Number(maxTotal) : null,
      icon: icon || null,
      depends_on_option_id: dependsOn || null,
    };
    try {
      const res = editing
        ? await fetch(`${optionsBase}/${editing.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) })
        : await fetch(optionsBase, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) });
      if (!res.ok) { setError((await res.json().catch(() => ({}))).error || "Could not save"); return; }
      const { option } = await res.json();
      const mapped = (prev?: OptionData): OptionData => ({
        id: option.id, name: option.name, description: option.description, option_type: option.option_type,
        choices: option.choices, is_required: option.is_required, max_total: option.max_total, icon: option.icon,
        depends_on_option_id: option.depends_on_option_id, price_cents: prev?.price_cents ?? 0, items: prev?.items ?? [],
      });
      setOptions((prev) => (editing ? prev.map((o) => (o.id === editing.id ? mapped(o) : o)) : [...prev, mapped()]));
      setFormOpen(false);
    } finally {
      setBusy(false);
    }
  }

  async function deleteOption(o: OptionData) {
    setBusy(true);
    try {
      const res = await fetch(`${optionsBase}/${o.id}`, { method: "DELETE" });
      if (!res.ok) { setError((await res.json().catch(() => ({}))).error || "Could not delete"); return; }
      setAvailable((prev) => [...prev, ...o.items].sort((a, b) => a.name.localeCompare(b.name)));
      setOptions((prev) => prev.filter((x) => x.id !== o.id));
      setConfirmDel(null);
    } finally {
      setBusy(false);
    }
  }

  async function setItemOption(item: OptItem, optionId: string | null) {
    const res = await fetch(`${costBase}/${item.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ linked_option_id: optionId }) });
    if (!res.ok) { setError((await res.json().catch(() => ({}))).error || "Could not update"); return false; }
    return true;
  }

  async function linkItem(option: OptionData, item: OptItem) {
    if (busy) return;
    setBusy(true); setError(null);
    try {
      if (!(await setItemOption(item, option.id))) return;
      setAvailable((prev) => prev.filter((i) => i.id !== item.id));
      setOptions((prev) => prev.map((o) => {
        if (o.id !== option.id) return o;
        const items = [...o.items, item];
        return { ...o, items, price_cents: priceOf(items) };
      }));
    } finally {
      setBusy(false);
    }
  }

  async function unlinkItem(option: OptionData, item: OptItem) {
    if (busy) return;
    setBusy(true); setError(null);
    try {
      if (!(await setItemOption(item, null))) return;
      setOptions((prev) => prev.map((o) => {
        if (o.id !== option.id) return o;
        const items = o.items.filter((i) => i.id !== item.id);
        return { ...o, items, price_cents: priceOf(items) };
      }));
      setAvailable((prev) => [...prev, item].sort((a, b) => a.name.localeCompare(b.name)));
    } finally {
      setBusy(false);
    }
  }

  const addingToLive = addingTo ? options.find((o) => o.id === addingTo.id) || null : null;
  const availableGroups = groupItems(available);

  return (
    <div>
      {error && <p className={styles.formError} style={{ marginTop: 12 }}>{error}</p>}

      <div className={styles.titleRow} style={{ marginTop: 18 }}>
        <p className={styles.sectionLabel} style={{ marginBottom: 0 }}>Options ({options.length})</p>
        <button type="button" className={styles.circleAdd} aria-label="Add option" onClick={openCreate}>
          <svg width="15" height="15" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 5v14M5 12h14" /></svg>
        </button>
      </div>

      {options.length === 0 ? (
        <p className={styles.dnsHint} style={{ marginTop: 10 }}>No options yet. Add one, pick its type, then bundle the costs it covers.</p>
      ) : (
        <div className={styles.finGroups} style={{ marginTop: 10 }}>
          {options.map((o) => (
            <div key={o.id} className={styles.finGroup}>
              <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", gap: 10 }}>
                <p className={styles.finGroupHead} style={{ margin: 0 }}>
                  {o.icon ? `${o.icon} ` : ""}{o.name}{o.is_required ? " *" : ""}
                  <span className={styles.roleBadge} style={{ marginLeft: 8 }}>{typeLabel(o.option_type)}</span>
                </p>
                <span className={styles.finRowAmount}>{dollars(o.price_cents)}</span>
              </div>
              {o.description && <p className={styles.roundFormHint} style={{ margin: "2px 0 6px" }}>{o.description}</p>}
              {o.choices && o.choices.length > 0 && (
                <p className={styles.roundFormHint} style={{ margin: "2px 0 6px" }}>Choices: {o.choices.map((c) => c.label).join(", ")}</p>
              )}

              {o.items.length === 0 ? (
                <p className={styles.dnsHint} style={{ marginTop: 4 }}>No costs bundled. A $0 option is a free opt-in.</p>
              ) : (
                <div className={styles.memberList} style={{ marginTop: 4 }}>
                  {o.items.map((it) => (
                    <div key={it.id} className={styles.finRow}>
                      <div className={styles.finRowMain}><span className={styles.finRowName}>{it.name}</span></div>
                      <span className={styles.finRowAmount}>{dollars(it.amount_cents)}</span>
                      <button type="button" className={styles.removeBtn} onClick={() => unlinkItem(o, it)} disabled={busy} style={{ marginLeft: 8 }}>Remove</button>
                    </div>
                  ))}
                </div>
              )}

              <div style={{ display: "flex", gap: 8, marginTop: 10, flexWrap: "wrap" }}>
