"use client";

import { useState } from "react";
import styles from "@/app/new/new.module.css";

export interface MemberOption {
  id: string;
  name: string;
  description: string | null;
  price_cents: number;
}

function dollars(cents: number): string {
  return `$${(cents / 100).toLocaleString("en-US", { minimumFractionDigits: cents % 100 === 0 ? 0 : 2, maximumFractionDigits: 2 })}`;
}

function Check({ on }: { on: boolean }) {
  return (
    <span className={styles.finCheck} data-on={on || undefined} aria-hidden style={{ cursor: "inherit" }}>
      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3.5} strokeLinecap="round" strokeLinejoin="round">
        <path d="M5 13l4 4L19 7" />
      </svg>
    </span>
  );
}

/**
 * Member-facing opt-in options (#216). Pick an option, all-or-nothing, and it enrolls
 * you into every contest it bundles (server-side). Shows each option as one line with
 * its price; never the contests inside (per the members-see-bundles rule). Trip Cost
 * shows as the always-included line when you're attending. "Your total" is the derived
 * charge (payments/balance land in slice 3).
 */
export default function OptionsModule({
  eventId,
  options,
  initialSelectedIds,
  tripCostCents,
  onRoster,
}: {
  eventId: string;
  options: MemberOption[];
  initialSelectedIds: string[];
  tripCostCents: number;
  onRoster: boolean;
}) {
  const [selected, setSelected] = useState<Set<string>>(() => new Set(initialSelectedIds));
  const [busy, setBusy] = useState<string | null>(null);

  async function toggle(o: MemberOption) {
    if (busy) return;
    const isOn = selected.has(o.id);
    setBusy(o.id);
    setSelected((prev) => { const n = new Set(prev); if (isOn) n.delete(o.id); else n.add(o.id); return n; });
    try {
      const res = await fetch(`/api/v2/events/${eventId}/options/${o.id}/selection`, { method: isOn ? "DELETE" : "POST" });
      if (!res.ok) throw new Error();
    } catch {
      setSelected((prev) => { const n = new Set(prev); if (isOn) n.add(o.id); else n.delete(o.id); return n; });
    } finally {
      setBusy(null);
    }
  }

  const selectedTotal = options.filter((o) => selected.has(o.id)).reduce((s, o) => s + o.price_cents, 0);
  const total = (onRoster ? tripCostCents : 0) + selectedTotal;

  return (
    <div className={styles.module}>
      <div className={styles.moduleHead}>
        <span className={styles.sectionLabel}>Options</span>
      </div>
      <div className={styles.optCard}>
        <div className={styles.optList}>
          {onRoster && tripCostCents > 0 && (
            <div className={styles.optRow} style={{ cursor: "default" }}>
              <Check on />
              <div className={styles.optMain}>
                <span className={styles.optName}>Trip Cost</span>
                <span className={styles.optSub}>Included because you&apos;re attending</span>
              </div>
              <span className={styles.optPrice}>{dollars(tripCostCents)}</span>
            </div>
          )}
          {options.map((o) => {
            const on = selected.has(o.id);
            return (
              <button key={o.id} type="button" className={styles.optRow} onClick={() => toggle(o)} disabled={busy !== null} aria-pressed={on}>
                <Check on={on} />
                <div className={styles.optMain}>
                  <span className={styles.optName}>{o.name}</span>
                  {o.description && <span className={styles.optSub}>{o.description}</span>}
                </div>
                <span className={styles.optPrice}>{o.price_cents ? dollars(o.price_cents) : "Free"}</span>
              </button>
            );
          })}
        </div>
        <div className={styles.optTotalRow}>
          <span>Your total</span>
          <strong>{dollars(total)}</strong>
        </div>
      </div>
    </div>
  );
}

