import { redirect } from "next/navigation";
import { getPlatformContext } from "@/lib/v2/context";
import { v2ServerClient } from "@/lib/v2/supabase";
import { v2Now } from "@/lib/v2/simulator";
import { OPTION_SELECT, loadOptionChoicePrices, tripCostCents, loadOptionSettings, optionsAreOpen, type Option } from "@/lib/v2/options";
import OptionsModule from "../OptionsModule";
import styles from "@/app/new/new.module.css";

/**
 * Member options page (#218) — the full list, reached from the "Everything" menu.
 * Editable while open; read-only once the deadline passes (is_open but expired).
 * Not reachable when options are closed (is_open=false) — the menu hides it then.
 */
export default async function MemberOptionsPage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;
  const ctx = await getPlatformContext();
  if (!ctx) redirect("/new/signup");
  const org = ctx.orgs.find((o) => o.slug === slug);
  if (!org) redirect("/new");

  const supabase = await v2ServerClient();
  const { data: ev } = await supabase
    .from("v2_events").select("id, name").eq("org_id", org.id).eq("status", "active").order("start_date", { ascending: false }).limit(1).maybeSingle();
  if (!ev) redirect(`/new/${slug}`);
  const eventId = ev.id as string;

  const settings = await loadOptionSettings(supabase, eventId);
  if (!settings.is_open) redirect(`/new/${slug}`); // closed → not available

  const [{ data: optRows }, { data: grpRows }, { data: selRows }, { data: rsvp }, { data: tcRow }] = await Promise.all([
    supabase.from("v2_options").select(OPTION_SELECT).eq("event_id", eventId).neq("option_type", "trip_cost").order("sort_order"),
    supabase.from("v2_option_groups").select("id, name, icon, sort_order").eq("event_id", eventId).order("sort_order"),
    supabase.from("v2_user_option_selections").select("option_id, value").eq("event_id", eventId).eq("user_id", ctx.userId),
    supabase.from("v2_event_participants").select("likelihood").eq("event_id", eventId).eq("user_id", ctx.userId).maybeSingle(),
    supabase.from("v2_options").select("id").eq("event_id", eventId).eq("option_type", "trip_cost").maybeSingle(),
  ]);
  const options = (optRows || []) as Option[];
  const [priceInfo, tc] = await Promise.all([loadOptionChoicePrices(supabase, options.map((o) => o.id)), tripCostCents(supabase, eventId)]);
  const open = optionsAreOpen(settings, (await v2Now()).getTime());
  const onRoster = (rsvp?.likelihood as number | undefined) === 99;

  const memberOptions = options.map((o) => ({
    id: o.id, name: o.name, description: o.description, option_type: o.option_type, choices: o.choices,
    is_required: o.is_required, max_total: o.max_total, icon: o.icon, group_id: o.group_id,
    depends_on_option_id: o.depends_on_option_id, price_info: priceInfo.get(o.id) || { whole: 0, byChoice: {} },
  }));
  const selections: Record<string, unknown> = {};
  for (const s of (selRows as { option_id: string; value: unknown }[] | null) ?? []) selections[s.option_id] = s.value;
  const groups = ((grpRows as { id: string; name: string; icon: string | null }[] | null) ?? []).map((g) => ({ id: g.id, name: g.name, icon: g.icon }));

  return (
    <div className={`${styles.page} ${styles.orgPage}`}>
      <h1 className={styles.title}>Options</h1>
      <p className={styles.lede} style={{ marginTop: 6 }}>
        {open ? "Your add-ons for the event. Change them any time before the deadline." : "Selections are closed. Here's a summary of your choices."}
      </p>
      <OptionsModule
        eventId={eventId}
        options={memberOptions}
        groups={groups}
        initialSelections={selections}
        tripCostCents={tc}
        tripCostOptionId={(tcRow?.id as string | undefined) ?? null}
        onRoster={onRoster}
        optionsOpen={open}
      />
    </div>
  );
}

