      .from("v2_notifications")
      .select("id", { count: "exact", head: true })
      .eq("user_id", ctx.userId)
      .eq("org_id", org.id)
      .eq("read", false)
      .not("type", "in", "(chat_message,chat_mention)"),
    supabase.from("v2_chat_room_members").select("room_id, hidden_at").eq("user_id", ctx.userId),
