import { NextRequest, NextResponse } from "next/server";
import { v2AdminClient } from "@/lib/v2/supabase";
import { sendV2Notifications } from "@/lib/v2/notifications";

/**
 * Cron (#218): fire each event's authored "options are open" notification once its
 * scheduled open time passes. Bearer-authed (CRON_SECRET). Claims the one-time
 * open_notification_sent_at tombstone atomically, so it never double-sends.
 */
export async function GET(request: NextRequest) {
  const authHeader = request.headers.get("authorization");
  if (authHeader !== `Bearer ${process.env.CRON_SECRET}`) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const admin = v2AdminClient();
  const nowIso = new Date().toISOString();
  const { data: due, error } = await admin
    .from("v2_event_option_settings")
    .select("event_id, open_notification_title, open_notification_body")
    .eq("is_open", true)
    .is("open_notification_sent_at", null)
    .not("open_notification_title", "is", null)
    .not("selection_open_at", "is", null)
    .lte("selection_open_at", nowIso);
  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
  if (!due?.length) return NextResponse.json({ processed: 0 });

  let processed = 0;
  for (const s of due) {
    // Claim atomically so overlapping runs don't double-send.
    const { data: claimed } = await admin
      .from("v2_event_option_settings")
      .update({ open_notification_sent_at: nowIso })
      .eq("event_id", s.event_id as string).is("open_notification_sent_at", null)
      .select("event_id");
    if (!claimed?.length) continue;

    try {
      const { data: ev } = await admin.from("v2_events").select("org_id").eq("id", s.event_id as string).maybeSingle();
      const orgId = ev?.org_id as string | undefined;
      if (!orgId) continue;
      const { data: orgRow } = await admin.from("v2_organizations").select("slug").eq("id", orgId).maybeSingle();
      const slug = orgRow?.slug as string | undefined;
      const { data: members } = await admin
        .from("v2_memberships").select("user_id").eq("org_id", orgId).eq("status", "active").is("archived_at", null);
      const ids = (members || []).map((m) => m.user_id as string);
      if (ids.length) {
        await sendV2Notifications(admin, ids, {
          orgId,
          type: "options_open",
          title: s.open_notification_title as string,
          body: (s.open_notification_body as string | null) || undefined,
          data: slug ? { url: `/new/${slug}/options` } : {},
        });
      }
      processed++;
    } catch (err) {
      console.error(`Cron v2-options-open: failed for ${s.event_id}:`, err);
    }
  }

  return NextResponse.json({ processed });
}

