3	import { useMemo, useState } from "react";
4	import Link from "next/link";
5	import { useRouter } from "next/navigation";
6	import {
7	  FEATURE_BUCKETS,
8	  MAX_PINNED,
9	  type FeatureScope,
10	  type FeatureVisibility,
11	  type ResolvedFeature,
12	} from "@/lib/v2/features";
13	import FeatureIcon from "@/app/new/_components/FeatureIcon";
14	import styles from "@/app/new/new.module.css";
15	
16	/** The editable slice of a feature's config. */
17	interface Draft {
18	  visibility: FeatureVisibility;
19	  pinned: boolean;
20	  isPublic: boolean;
21	  label: string; // label override; empty = use catalog label
22	}
23	
24	function toDraft(f: ResolvedFeature): Draft {
25	  return {
26	    visibility: f.visibility,
27	    pinned: f.pinned,
28	    isPublic: f.public,
29	    label: f.label === f.def.label ? "" : f.label,
30	  };
31	}
32	
33	const VIS_ORDER: FeatureVisibility[] = ["off", "everyone", "admins"];
34	const VIS_LABEL: Record<FeatureVisibility, string> = {
35	  off: "Off",
36	  everyone: "Everyone",
37	  admins: "Admins",
38	};
39	const nextVisibility = (v: FeatureVisibility): FeatureVisibility =>
40	  VIS_ORDER[(VIS_ORDER.indexOf(v) + 1) % VIS_ORDER.length];
41	
42	/**
43	 * Shared feature-registry editor for both scopes. `scope='group'` edits org-wide
44	 * features (Articles, Music…); `scope='event'` edits per-event features and adds
45	 * bottom-bar pinning (≤3). Each feature is a three-state toggle: Off / Everyone /
46	 * Admins-only. Top-bar utilities (Chat/Photos/Music) toggle only — no pin/public.
47	 */
48	export default function FeaturesConfig({
49	  scope,
50	  endpoint,
51	  initial,
52	  backHref,
53	  backLabel,
54	  eyebrow,
55	  title,
56	  intro,
57	}: {
58	  scope: FeatureScope;
59	  endpoint: string; // PUT target
60	  initial: ResolvedFeature[];
61	  backHref: string;
62	  backLabel: string;
63	  eyebrow: string;
64	  title: string;
65	  intro: string;
66	}) {
67	  const router = useRouter();
68	  const allowPin = scope === "event";
69	
70	  const scoped = useMemo(() => initial.filter((f) => f.def.scope === scope), [initial, scope]);
71	  const editableKeys = useMemo(
72	    () => scoped.filter((f) => f.def.status === "available" && !f.def.alwaysOn).map((f) => f.def.key),
73	    [scoped],
74	  );
75	  const [drafts, setDrafts] = useState<Record<string, Draft>>(() =>
76	    Object.fromEntries(
77	      scoped
78	        .filter((f) => f.def.status === "available" && !f.def.alwaysOn)
79	        .map((f) => [f.def.key, toDraft(f)]),
80	    ),
81	  );
82	  const [saving, setSaving] = useState(false);
83	  const [error, setError] = useState<string | null>(null);
84	  const [savedAt, setSavedAt] = useState(0);
85	
86	  const pinnedCount = allowPin
87	    ? editableKeys.filter((k) => drafts[k]?.visibility !== "off" && drafts[k]?.pinned).length
88	    : 0;
89	  const pinFull = pinnedCount >= MAX_PINNED;
90	
91	  function patch(key: string, next: Partial<Draft>) {
92	    setSavedAt(0);
93	    setDrafts((d) => {
94	      const cur = d[key];
95	      if (!cur) return d;
96	      const merged = { ...cur, ...next };
97	      if (next.visibility === "off") {
98	        merged.pinned = false;
99	        merged.isPublic = false;
100	      }
101	      // Spectator-public only applies when it's on for everyone.
102	      if (merged.visibility !== "everyone") merged.isPublic = false;
103	      return { ...d, [key]: merged };
104	    });
105	  }
106	
