export interface OptionSettings {
  is_open: boolean;
  selection_open_at: string | null;   // scheduled auto-open (null = already open)
  selection_deadline: string | null;  // auto-close
  open_notification_title: string | null;
  open_notification_body: string | null;
  open_notification_sent_at: string | null;
}

/** Per-event option settings; defaults to the master switch on, no window. */
export async function loadOptionSettings(admin: SupabaseClient, eventId: string): Promise<OptionSettings> {
  const { data } = await admin
    .from("v2_event_option_settings")
    .select("is_open, selection_open_at, selection_deadline, open_notification_title, open_notification_body, open_notification_sent_at")
    .eq("event_id", eventId).maybeSingle();
  return {
    is_open: (data?.is_open as boolean | undefined) ?? true,
    selection_open_at: (data?.selection_open_at as string | null) ?? null,
    selection_deadline: (data?.selection_deadline as string | null) ?? null,
