3	import { useState } from "react";
4	import {
5	  DndContext, closestCenter, PointerSensor, TouchSensor, useSensor, useSensors, type DragEndEvent,
6	} from "@dnd-kit/core";
7	import { SortableContext, useSortable, verticalListSortingStrategy, arrayMove } from "@dnd-kit/sortable";
8	import { CSS } from "@dnd-kit/utilities";
9	import Modal from "@/app/new/_components/Modal";
10	import ConfirmModal from "@/app/new/_components/ConfirmModal";
11	import { OPTION_TYPES, typeHasChoices, type OptionType, type OptionChoice, type OptionSettings } from "@/lib/v2/options";
12	import { OPTION_ICON_CATEGORIES } from "@/lib/v2/option-icons";
13	import styles from "@/app/new/new.module.css";
14	
15	export interface OptItem {
16	  id: string; name: string; amount_cents: number; source_type: string;
17	  group_key: string; group_label: string; sort_order: number;
18	  choice_value: string | null; // which choice this cost funds (null = whole option)
19	}
20	export interface OptionData {
21	  id: string; name: string; description: string | null; group_id: string | null;
22	  option_type: OptionType; choices: OptionChoice[] | null; is_required: boolean;
23	  max_total: number | null; icon: string | null; depends_on_option_id: string | null;
24	  price_cents: number; items: OptItem[];
25	}
26	export interface GroupData { id: string; name: string; description: string | null; icon: string | null }
27	
28	function groupItems(items: OptItem[]): { key: string; label: string; list: OptItem[] }[] {
29	  const byKey = new Map<string, { label: string; list: OptItem[] }>();
30	  for (const i of items) {
31	    const g = byKey.get(i.group_key) || byKey.set(i.group_key, { label: i.group_label, list: [] }).get(i.group_key)!;
32	    g.list.push(i);
33	  }
34	  for (const g of byKey.values()) g.list.sort((a, b) => a.sort_order - b.sort_order || a.name.localeCompare(b.name));
35	  return [...byKey.entries()]
36	    .sort((a, b) => (a[0].startsWith("contest:") ? 0 : 1) - (b[0].startsWith("contest:") ? 0 : 1) || a[1].label.localeCompare(b[1].label))
37	    .map(([key, v]) => ({ key, label: v.label, list: v.list }));
38	}
39	function dollars(cents: number): string {
40	  return `$${(cents / 100).toLocaleString("en-US", { minimumFractionDigits: cents % 100 === 0 ? 0 : 2, maximumFractionDigits: 2 })}`;
41	}
42	const priceOf = (items: OptItem[]) => items.reduce((s, i) => s + i.amount_cents, 0);
43	const typeLabel = (t: OptionType) => OPTION_TYPES.find((x) => x.type === t)?.label ?? t;
44	
45	type ChoiceDraft = { label: string; value: string };
46	
47	/** One option as a draggable accordion; header toggles, body = the editor (children). */
