  const body: Record<string, unknown> = { linked_option_id: optionId };
  if (choiceValues !== undefined) body.choice_values = choiceValues;
  const res = await fetch(`${costBase}/${item.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
  if (!res.ok) { setError((await res.json().catch(() => ({}))).error || "Could not update"); return false; }
  return true;
}
async function linkItem(option: OptionData, item: OptItem, choiceValues: string[]) {
  if (busy) return;
  setBusy(true); setError(null);
  try {
    if (!(await setItemOption(item, option.id, choiceValues))) return;
    const placed: OptItem = { ...item, choice_values: choiceValues };
    setAvailable((prev) => prev.filter((i) => i.id !== item.id));
    setOptions((prev) => prev.map((o) => (o.id === option.id ? { ...o, items: [...o.items, placed], price_cents: priceOf([...o.items, placed]) } : o)));
  } finally { setBusy(false); }
}
// Change which choices an already-bundled cost funds (e.g. drop Monday dinner from
// the late-arrival choices). Whole-option when none are selected.
async function updateItemChoices(option: OptionData, item: OptItem, choiceValues: string[]) {
  if (busy) return;
  setBusy(true); setError(null);
  try {
    if (!(await setItemOption(item, option.id, choiceValues))) return;
    setOptions((prev) => prev.map((o) => (o.id === option.id
      ? { ...o, items: o.items.map((i) => (i.id === item.id ? { ...i, choice_values: choiceValues } : i)) }
      : o)));
    setEditChoicesFor(null);
  } finally { setBusy(false); }
}
async function unlinkItem(option: OptionData, item: OptItem) {
