async function reorderOptionsInGroup(gid: string | null, e: DragEndEvent) {
  const { active, over } = e;
  if (!over || active.id === over.id) return;
  const groupOpts = optsOf(gid);
  const oldIdx = groupOpts.findIndex((o) => o.id === active.id);
  const newIdx = groupOpts.findIndex((o) => o.id === over.id);
  if (oldIdx < 0 || newIdx < 0) return;
  const moved = arrayMove(groupOpts, oldIdx, newIdx);
  // Rebuild the global list keeping other groups' options in place.
  const movedIds = new Set(moved.map((o) => o.id));
  let mi = 0;
  const before = options;
  const next = options.map((o) => (movedIds.has(o.id) ? moved[mi++] : o));
  setOptions(next);
  try {
    await Promise.all(moved.map((o, i) =>
      fetch(`${optionsBase}/${o.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ sort_order: i }) })
        .then((r) => { if (!r.ok) throw new Error(); })));
    setError(null);
  } catch { setOptions(before); setError("Could not save the new order"); }
}

// ── Groups ───────────────────────────────────────────────────────────────
function openGroupCreate() { setEditingGroup(null); setGName(""); setGIcon(""); setGDesc(""); setGIconOpen(false); setError(null); setGroupModal(true); }
function openGroupEdit(g: GroupData) { setEditingGroup(g); setGName(g.name); setGIcon(g.icon || ""); setGDesc(g.description || ""); setGIconOpen(false); setError(null); setGroupModal(true); }

async function submitGroup(e: React.FormEvent) {
  e.preventDefault();
  if (busy) return;
  if (!gName.trim()) { setError("Name is required"); return; }

