1	import { NextResponse } from "next/server";
2	import { v2GetUser, v2AdminClient } from "@/lib/v2/supabase";
3	import { isOrgAdmin } from "@/lib/v2/orgs";
4	import { OPTION_SELECT, OPTION_TYPES, normalizeChoices, type Option, type OptionType } from "@/lib/v2/options";
5	
6	type Params = Promise<{ id: string; eventId: string; optionId: string }>;
7	
8	const EDITABLE = new Set(["name", "description", "sort_order", "group_id", "is_required", "icon", "depends_on_option_id"]);
9	
10	/** Edit an option (#216). Admins only. */
11	export async function PATCH(request: Request, { params }: { params: Params }) {
12	  const { userId } = await v2GetUser(request);
13	  if (!userId) return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
14	  const { id: orgId, eventId, optionId } = await params;
15	
16	  const admin = v2AdminClient();
17	  if (!(await isOrgAdmin(admin, userId, orgId))) return NextResponse.json({ error: "Admins only" }, { status: 403 });
18	
19	  let body: Record<string, unknown>;
20	  try {
21	    body = await request.json();
22	  } catch {
23	    return NextResponse.json({ error: "Invalid body" }, { status: 400 });
24	  }
25	  const patch: Record<string, unknown> = {};
26	  for (const [k, v] of Object.entries(body)) if (EDITABLE.has(k)) patch[k] = v;
27	  if ("name" in patch) {
28	    const n = String(patch.name || "").trim();
29	    if (!n) return NextResponse.json({ error: "Name can't be empty" }, { status: 400 });
