1	import { NextResponse } from "next/server";
2	import { v2GetUser, v2AdminClient } from "@/lib/v2/supabase";
3	import { isOrgMember, orgNameMode } from "@/lib/v2/orgs";
4	import { pickName } from "@/lib/v2/profile";
5	import { logActivity } from "@/lib/v2/activity";
6	import { syncEventChannelMembership } from "@/lib/v2/chat/channels";
7	import { syncAttendanceEnrollment } from "@/lib/v2/contests/enrollment";
8	
9	/**
10	 * RSVP for an event. Mirrors the legacy model: a member sets their attendance
11	 * *likelihood* (25/50/75/99). 99 ("Attending") marks them on_roster. DELETE
12	 * clears the RSVP. Returns the caller's likelihood plus the attending count
13	 * (on_roster). Auth: bearer (native) or cookie (web). Membership-gated.
14	 *
15	 * NOTE: the legacy site also cascades contest/roster enrollment on attend/leave.
16	 * v2 has no contest system yet, so we only persist likelihood + on_roster here;
17	 * enrollment sync lands when v2 contests do.
18	 */
19	
20	const LIKELIHOODS = [25, 50, 75, 99];
21	const LIKELIHOOD_LABEL: Record<number, string> = {
22	  99: "Attending",
23	  75: "Probable",
24	  50: "Questionable",
25	  25: "Doubtful",
26	};
27	
28	async function resolve(request: Request, eventId: string) {
29	  const { userId } = await v2GetUser(request);
30	  if (!userId) return { error: "Not authenticated", status: 401 as const };
31	  const admin = v2AdminClient();
32	  const { data: event } = await admin
33	    .from("v2_events")
34	    .select("id, org_id")
35	    .eq("id", eventId)
36	    .maybeSingle();
37	  if (!event) return { error: "Event not found", status: 404 as const };
38	  if (!(await isOrgMember(admin, userId, event.org_id))) {
39	    return { error: "Not a member", status: 403 as const };
40	  }
41	  return { admin, userId, orgId: event.org_id as string };
42	}
43	
44	async function attendingCount(
45	  admin: ReturnType<typeof v2AdminClient>,
46	  eventId: string,
47	): Promise<number> {
48	  const { count } = await admin
49	    .from("v2_event_participants")
50	    .select("id", { count: "exact", head: true })
51	    .eq("event_id", eventId)
52	    .eq("on_roster", true);
53	  return count ?? 0;
54	}
55	
56	export async function GET(
57	  request: Request,
58	  { params }: { params: Promise<{ eventId: string }> },
59	) {
60	  const { eventId } = await params;
61	  const g = await resolve(request, eventId);
62	  if ("error" in g) return NextResponse.json({ error: g.error }, { status: g.status });
63	
64	  const [{ data }, mode] = await Promise.all([
65	    g.admin
66	      .from("v2_event_participants")
67	      .select("user_id, likelihood, likelihood_set_at, on_roster, user:v2_profiles(display_name, first_name, last_name, avatar_url)")
68	      .eq("event_id", eventId),
69	    orgNameMode(g.admin, g.orgId),
70	  ]);
71	
72	  const rows = (data || []).map((r) => {
73	    const u = Array.isArray(r.user) ? r.user[0] : r.user;
74	    return {
75	      userId: r.user_id as string,
76	      likelihood: r.likelihood as number,
77	      likelihoodSetAt: (r.likelihood_set_at as string | null) ?? null,
78	      displayName: pickName(u, mode),
79	      avatarUrl: (u?.avatar_url as string | null) ?? null,
80	    };
81	  });
82	
83	  const mine = rows.find((r) => r.userId === g.userId);
84	  return NextResponse.json({
85	    likelihood: mine?.likelihood ?? null,
86	    attendingCount: (data || []).filter((r) => r.on_roster).length,
87	    responseCount: rows.length,
88	    participants: rows,
89	  });
90	}
91	
92	export async function POST(
93	  request: Request,
94	  { params }: { params: Promise<{ eventId: string }> },
95	) {
96	  const { eventId } = await params;
97	  const g = await resolve(request, eventId);
98	  if ("error" in g) return NextResponse.json({ error: g.error }, { status: g.status });
99	
100	  let body: { likelihood?: number };
101	  try {
102	    body = await request.json();
103	  } catch {
104	    return NextResponse.json({ error: "Invalid body" }, { status: 400 });
105	  }
106	  const likelihood = body.likelihood;
107	  if (!LIKELIHOODS.includes(likelihood as number)) {
108	    return NextResponse.json(
109	      { error: "likelihood must be 25, 50, 75, or 99" },
110	      { status: 400 },
111	    );
112	  }
113	  const onRoster = likelihood === 99;
114	
115	  // Pre-read prior likelihood so we log only a *genuine change* (not a re-confirm
116	  // of the same level). Any move between levels is feed-worthy.
117	  const { data: prior } = await g.admin
118	    .from("v2_event_participants")
119	    .select("likelihood")
120	    .eq("event_id", eventId)
121	    .eq("user_id", g.userId)
122	    .maybeSingle();
123	  const priorLikelihood = (prior?.likelihood as number | undefined) ?? null;
124	
125	  const { error } = await g.admin.from("v2_event_participants").upsert(
126	    {
127	      event_id: eventId,
128	      org_id: g.orgId,
129	      user_id: g.userId,
130	      likelihood,
131	      on_roster: onRoster,
132	      likelihood_set_at: new Date().toISOString(),
133	      updated_at: new Date().toISOString(),
134	    },
135	    { onConflict: "event_id,user_id" },
136	  );
137	  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
138	
139	  // Managed event channel: opting in (on_roster) adds you with full history;
140	  // dropping below "Attending" removes you (your past messages stay). Best-effort.
141	  await syncEventChannelMembership(g.admin, eventId, g.userId, onRoster).catch(() => {});
142	
143	  // Included contests (#215): becoming on_roster auto-enrolls you into every
144	  // auto-enroll contest (minus explicit opt-outs). Additive only; the leave-roster
145	  // cascade + guards are #217. Best-effort — never block the RSVP.
146	  if (onRoster) {
147	    await syncAttendanceEnrollment(g.admin, eventId, g.userId, true).catch(() => {});
148	  }
149	
150	  // Activity feed: a row per genuine likelihood change. Title is the status only
151	  // ("Attending 99%") — the feed renders the actor's name + avatar itself.
152	  if (priorLikelihood !== likelihood) {
153	    await logActivity(g.admin, {
154	      orgId: g.orgId,
155	      eventId,
156	      kind: "rsvp",
157	      actorId: g.userId,
