export interface BalanceLine {
  label: string;
  sublabel: string | null;
  amountCents: number;
  derived: boolean; // true = Trip Cost / option (not a stored ledger row)
}
export interface LedgerTx {
  id: string;
  type: "charge" | "payment";
  source: string;
  amountCents: number;
  description: string | null;
  method: string | null;
  notes: string | null;
  createdAt: string;
}
