.balGrid {
  border: 1px solid var(--line);
  border-radius: 12px;
  overflow: hidden;
}
.balHead,
.balRow,
.balTotals {
  display: grid;
  grid-template-columns: 1fr auto auto auto;
  gap: 12px;
  align-items: center;
  padding: 10px 12px;
}
.balHead {
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--ink-soft);
  background: color-mix(in srgb, var(--ink) 3%, var(--card));
  border-bottom: 1px solid var(--line);
}
.balHead span:not(:first-child),
.balRow .balNum,
.balTotals .balNum { text-align: right; }
.balRow {
  width: 100%;
  border: none;
  border-bottom: 1px solid var(--line);
  background: var(--card);
  cursor: pointer;
  text-align: left;
  font: inherit;
}
.balRow:last-of-type { border-bottom: none; }
.balRow:hover { background: color-mix(in srgb, var(--brand) 5%, var(--card)); }
