export default function OptionsModule({
  eventId, options, groups, initialSelections, tripCostCents, tripCostOptionId, onRoster, optionsOpen,
}: {
  eventId: string;
  options: MemberOption[];
  groups: MemberGroup[];
  initialSelections: Record<string, unknown>;
  tripCostCents: number;
  tripCostOptionId: string | null;
  onRoster: boolean;
  optionsOpen: boolean;
}) {
  const [sel, setSel] = useState<Record<string, unknown>>(initialSelections);
  const [busyId, setBusyId] = useState<string | null>(null);

  const selectedOf = (o: MemberOption) => !isEmptyValue(o.option_type, sel[o.id]);

  async function save(o: MemberOption, value: unknown) {
    const prev = sel[o.id];
    const empty = isEmptyValue(o.option_type, value);
    setSel((s) => { const n = { ...s }; if (empty) delete n[o.id]; else n[o.id] = value; return n; });
    setBusyId(o.id);
    try {
      const url = `/api/v2/events/${eventId}/options/${o.id}/selection`;
      const res = empty
        ? await fetch(url, { method: "DELETE" })
        : await fetch(url, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ value }) });
      if (!res.ok) throw new Error();
    } catch {
      setSel((s) => { const n = { ...s }; if (prev === undefined) delete n[o.id]; else n[o.id] = prev; return n; });
    } finally {
      setBusyId(null);
    }
  }

  // Dependency gate: hide a dependent option until its parent is selected. A dependency
  // on the Trip Cost option means "requires attending" (you can't opt in unless you're
  // paying for the trip).
  const byId = new Map(options.map((o) => [o.id, o]));
  const visible = (o: MemberOption): boolean => {
    if (!o.depends_on_option_id) return true;
    if (tripCostOptionId && o.depends_on_option_id === tripCostOptionId) return onRoster;
    const parent = byId.get(o.depends_on_option_id);
    return parent ? selectedOf(parent) : true;
  };

