3	import { useCallback, useState } from "react";
4	import Modal from "@/app/new/_components/Modal";
5	import styles from "@/app/new/new.module.css";
6	/* eslint-disable @next/next/no-img-element */
7	
8	// Mirrors the legacy RSVP model: an attendance likelihood, not a going/maybe enum.
9	export type Likelihood = 25 | 50 | 75 | 99;
10	
11	const OPTIONS: { value: Likelihood; label: string; description: string }[] = [
12	  { value: 99, label: "Attending", description: "99% - I'll be there" },
13	  { value: 75, label: "Probable", description: "75% - Looking good" },
14	  { value: 50, label: "Questionable", description: "50% - Still figuring it out" },
15	  { value: 25, label: "Doubtful", description: "25% - Unlikely but possible" },
16	];
17	
18	const LABEL: Record<Likelihood, string> = {
19	  99: "Attending",
20	  75: "Probable",
21	  50: "Questionable",
22	  25: "Doubtful",
23	};
24	
25	interface Participant {
26	  userId: string;
27	  likelihood: number;
28	  likelihoodSetAt: string | null;
29	  displayName: string;
30	  avatarUrl: string | null;
31	}
32	
33	/**
34	 * Event RSVP. Until the user responds it's a bold, pulsing brand CTA; once they
35	 * do it becomes a "Responses" accordion (mirrors legacy): their own response +
36	 * an expandable breakdown of everyone's choice grouped by likelihood. Writes to
37	 * /api/v2/events/[eventId]/rsvp (cookie auth on web).
38	 */
39	export default function RsvpModule({
40	  eventId,
41	  eventName,
42	  initialLikelihood,
43	  initialResponseCount,
44	  initialAttendingCount,
45	}: {
46	  eventId: string;
47	  eventName: string;
48	  initialLikelihood: Likelihood | null;
49	  initialResponseCount: number;
50	  initialAttendingCount: number;
51	}) {
52	  const [likelihood, setLikelihood] = useState<Likelihood | null>(initialLikelihood);
53	  const [responseCount, setResponseCount] = useState(initialResponseCount);
54	  const [attendingCount, setAttendingCount] = useState(initialAttendingCount);
55	  const [participants, setParticipants] = useState<Participant[] | null>(null);
56	  const [expanded, setExpanded] = useState(false);
57	  const [open, setOpen] = useState(false);
58	  const [saving, setSaving] = useState(false);
59	  const [error, setError] = useState<string | null>(null);
60	
61	  const loadParticipants = useCallback(async () => {
62	    try {
63	      const res = await fetch(`/api/v2/events/${eventId}/rsvp`);
64	      if (!res.ok) return;
65	      const d = await res.json();
66	      setParticipants(d.participants || []);
67	      setResponseCount(d.responseCount ?? 0);
68	      setAttendingCount(d.attendingCount ?? 0);
69	      setLikelihood(d.likelihood ?? null);
70	    } catch {
71	      /* ignore */
72	    }
73	  }, [eventId]);
74	
75	  function toggleExpanded() {
76	    const next = !expanded;
77	    setExpanded(next);
78	    if (next && participants === null) loadParticipants();
79	  }
80	
81	  async function choose(next: Likelihood) {
82	    setSaving(true);
83	    setError(null);
84	    try {
85	      const res = await fetch(`/api/v2/events/${eventId}/rsvp`, {
86	        method: "POST",
87	        headers: { "Content-Type": "application/json" },
88	        body: JSON.stringify({ likelihood: next }),
89	      });
90	      if (!res.ok) throw new Error();
91	      setLikelihood(next);
92	      setOpen(false);
93	      setParticipants(null);
94	      await loadParticipants();
95	    } catch {
96	      setError("Couldn't save your RSVP. Try again.");
97	    } finally {
98	      setSaving(false);
99	    }
100	  }
101	
102	  async function clear() {
103	    setSaving(true);
104	    setError(null);
105	    try {
106	      const res = await fetch(`/api/v2/events/${eventId}/rsvp`, { method: "DELETE" });
107	      if (!res.ok) throw new Error();
108	      setLikelihood(null);
109	      setExpanded(false);
110	      setParticipants(null);
111	      setOpen(false);
112	    } catch {
113	      setError("Couldn't clear your RSVP. Try again.");
114	    } finally {
115	      setSaving(false);
116	    }
117	  }
118	
119	  return (
120	    <section className={styles.module}>
121	      {likelihood === null ? (
122	        <button type="button" className={styles.rsvpPrompt} onClick={() => setOpen(true)}>
123	          <span className={styles.rsvpEyebrow}>{eventName}</span>
124	          <span className={styles.rsvpBig}>Are you in?</span>
125	          <span className={styles.rsvpHint}>Tap to set your status</span>
126	        </button>
127	      ) : (
128	        <div className={styles.rsvpCard}>
129	          <button type="button" className={styles.rsvpAccordionHead} onClick={toggleExpanded}>
130	            <span className={styles.rsvpAccordionTitle}>
131	              Responses <span className={styles.rsvpCount}>({responseCount})</span>
132	              <span className={styles.rsvpAttending}>
133	                Attending <span className={styles.rsvpCount}>({attendingCount})</span>
134	              </span>
135	            </span>
136	            <svg
137	              className={styles.rsvpChevron}
138	              data-open={expanded || undefined}
139	              width="16" height="16" fill="none" stroke="currentColor" strokeWidth={2}
140	              strokeLinecap="round" strokeLinejoin="round" viewBox="0 0 24 24" aria-hidden
141	            >
142	              <path d="M6 9l6 6 6-6" />
143	            </svg>
144	          </button>
145	
146	          <button type="button" className={styles.rsvpYours} onClick={() => setOpen(true)}>
147	            <span className={styles.rsvpYoursLabel}>Your response</span>
148	            <span className={styles.rsvpYoursValue}>
149	              <span className={styles.rsvpDot} data-likelihood={likelihood} aria-hidden />
150	              {LABEL[likelihood]} {likelihood}%
151	              <svg width="13" height="13" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" viewBox="0 0 24 24" aria-hidden>
152	                <path d="M12 20h9M16.5 3.5a2.1 2.1 0 013 3L7 19l-4 1 1-4z" />
153	              </svg>
154	            </span>
155	          </button>
156	
157	          {expanded && (
