182	                            {p.displayName}
183	                          </span>
184	                        ))}
185	                      </div>
186	                    </div>
187	                  );
188	                })
189	              )}
190	            </div>
191	          )}
192	        </div>
193	      )}
194	
195	      <Modal open={open} title="How likely are you?" onClose={() => setOpen(false)}>
196	        <div className={styles.rsvpOptions}>
197	          {OPTIONS.map((o) => (
198	            <button
199	              key={o.value}
200	              type="button"
201	              className={styles.rsvpOption}
202	              data-selected={likelihood === o.value || undefined}
203	              disabled={saving}
204	              onClick={() => choose(o.value)}
205	            >
206	              <span className={styles.rsvpOptionDot} data-likelihood={o.value} aria-hidden />
207	              <span className={styles.rsvpOptionText}>
208	                <span className={styles.rsvpOptionLabel}>{o.label}</span>
209	                <span className={styles.rsvpOptionSub}>{o.description}</span>
210	              </span>
211	              {likelihood === o.value && <span className={styles.rsvpCheck} aria-hidden>✓</span>}
212	            </button>
