              {likelihood === o.value && <span className={styles.rsvpCheck} aria-hidden>✓</span>}
            </button>
          ))}
          {likelihood !== null && (
            <button type="button" className={styles.rsvpClear} disabled={saving} onClick={clear}>
              Clear my choice
            </button>
          )}
          {error && <p className={styles.formError}>{error}</p>}
        </div>
      </Modal>
    </section>
  );
}

