53	  const [responseCount, setResponseCount] = useState(initialResponseCount);
54	  const [attendingCount, setAttendingCount] = useState(initialAttendingCount);
55	  const [participants, setParticipants] = useState<Participant[] | null>(null);
56	  const [expanded, setExpanded] = useState(false);
57	  const [open, setOpen] = useState(false);
58	  const [error, setError] = useState<string | null>(null);
