60	  const loadParticipants = useCallback(async () => {
61	    try {
62	      const res = await fetch(`/api/v2/events/${eventId}/rsvp`);
63	      if (!res.ok) return;
64	      const d = await res.json();
65	      setParticipants(d.participants || []);
66	      setResponseCount(d.responseCount ?? 0);
67	      setAttendingCount(d.attendingCount ?? 0);
68	      setLikelihood(d.likelihood ?? null);
69	    } catch {
70	      /* ignore */
71	    }
72	  }, [eventId]);
