81	  function choose(next: Likelihood) {
82	    const prev = likelihood, prevResp = responseCount, prevAtt = attendingCount;
83	    setError(null);
84	    setLikelihood(next);
85	    setOpen(false);
86	    setParticipants(null); // breakdown reloads lazily next time it's expanded
