  optionsOpen: boolean;
}) {
  const router = useRouter();
  const [sel, setSel] = useState<Record<string, unknown>>(initialSelections);
  const [busyId, setBusyId] = useState<string | null>(null);
  // Trip Cost = "attending". You opt into it by RSVPing Attending, not by a toggle —
  // so the Trip Cost line drives the RSVP. Local state keeps the UI live after the call.
  const [roster, setRoster] = useState(onRoster);
  const [rsvpBusy, setRsvpBusy] = useState(false);
  const [confirmLeave, setConfirmLeave] = useState(false);

  const selectedOf = (o: MemberOption) => !isEmptyValue(o.option_type, sel[o.id]);

  async function setAttending(attending: boolean) {
    if (rsvpBusy) return;
    setRsvpBusy(true);
    const prev = roster;
    setRoster(attending);
    try {
      const url = `/api/v2/events/${eventId}/rsvp`;
      const res = attending
        ? await fetch(url, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ likelihood: 99 }) })
        : await fetch(url, { method: "DELETE" });
      if (!res.ok) throw new Error();
      setConfirmLeave(false);
