const systemName = orgSys?.system_name?.trim() || "System";
const systemAvatar = orgSys?.system_avatar_url ?? null;

// Options the member can opt into + their current picks + the derived Trip Cost.
const optionRows = (optionsRes.data as Option[] | null) ?? [];
const optionIds = optionRows.map((o) => o.id);
const [optionPriceInfo, tripCost] = await Promise.all([
  loadOptionChoicePrices(supabase, optionIds),
  tripCostCents(supabase, eventId),
]);
// Trip Cost is a special, unremovable derived option (#218). It's not a toggle —
// it renders as the always-present Trip Cost line, and other options depend on it.
const tripCostOptionId = optionRows.find((o) => o.option_type === "trip_cost")?.id ?? null;
const memberOptions = optionRows.filter((o) => o.option_type !== "trip_cost").map((o) => ({
  id: o.id, name: o.name, description: o.description, option_type: o.option_type, choices: o.choices,
  is_required: o.is_required, max_total: o.max_total, icon: o.icon, group_id: o.group_id,
  depends_on_option_id: o.depends_on_option_id, price_info: optionPriceInfo.get(o.id) || { whole: 0, byChoice: {} },
}));
const selections: Record<string, unknown> = {};
for (const s of ((selectionsRes.data as { option_id: string; value: unknown }[] | null) ?? [])) selections[s.option_id] = s.value;
const optionGroups = ((optionGroupsRes.data as { id: string; name: string; icon: string | null }[] | null) ?? []).map((g) => ({ id: g.id, name: g.name, icon: g.icon }));
const onRoster = myLikelihood === 99;

const birthdays = birthdaysToday(
  (membersRes.data as unknown as { v2_profiles: MemberProfile | null }[]) || [],
  nameDisplay,
  now,
);

// Featured article (null until 00185 is applied / an article is published).
const row = articleRes.error ? null : (articleRes.data as ArticleRow | null);
const rowAuthor = row ? (Array.isArray(row.author) ? row.author[0] : row.author) : null;
const article: FeaturedArticle | null = row
  ? {
      id: row.id,
      title: row.title,
      publishAt: row.publish_at,
      imageUrl: row.image_url,
      preview: stripMarkdown(row.content || "") || null,
      focalX: row.image_focal_x ?? 50,
      focalY: row.image_focal_y ?? 50,
      authorName: rowAuthor ? pickName(rowAuthor, nameDisplay) : null,
      authorAvatar: rowAuthor?.avatar_url ?? null,
    }
  : null;

return (
  <>
    <BirthdayBanner birthdays={birthdays} slug={slug} />
    {articlesVisible && article && <ArticleModule article={article} slug={slug} />}
    <RsvpModule
      eventId={eventId}
      eventName={eventName}
      initialLikelihood={myLikelihood}
      initialResponseCount={responseCount}
      initialAttendingCount={attendingCount}
    />
    {optionsOpen && (
      <OptionsReminder
        eventId={eventId}
        options={memberOptions}
        groups={optionGroups}
        initialSelections={selections}
        tripCostCents={tripCost}
        tripCostOptionId={tripCostOptionId}
        onRoster={onRoster}
      />
    )}
    <StoreModule storeUrl={storeEnabled ? storeUrl : null} storeLabel={storeLabel} />
    <ActivityFeed initialItems={activity} orgId={orgId} systemName={systemName} systemAvatar={systemAvatar} />

