/* Member option controls: switch (binary), radio (select), checkbox (multi) — v1 parity. */
.optChoiceList { display: flex; flex-direction: column; gap: 8px; }
.optChoiceRow {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 12px;
  border-radius: 12px;
  border: 1px solid var(--line);
  background: color-mix(in srgb, var(--ink) 2%, var(--card));
  color: var(--ink);
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease;
}
.optChoiceRow[data-on] {
  border-color: color-mix(in srgb, var(--brand) 40%, var(--line));
  background: color-mix(in srgb, var(--brand) 8%, var(--card));
}
.optChoiceRow:disabled { opacity: 0.5; cursor: default; }
.optChoiceMain { display: flex; align-items: center; gap: 10px; min-width: 0; }
.optChoiceLabel { font-size: 0.9rem; color: var(--ink); }
