                  onClick={() => save(o, v === c.value ? "" : c.value)}>{c.label}{p ? ` ${dollars(p)}` : ""}</button>
              );
            })}
          </div>
        );
      case "multi_select": {
        const arr = Array.isArray(v) ? (v as string[]) : [];
        return (
          <div className={styles.pillRow}>
            {(o.choices || []).map((c) => {
              const on = arr.includes(c.value);
              const p = o.price_info.byChoice[c.value] || 0;
              return (
                <button key={c.value} type="button" className={styles.pill} data-on={on || undefined} disabled={busy}
                  onClick={() => save(o, on ? arr.filter((x) => x !== c.value) : [...arr, c.value])}>{c.label}{p ? ` ${dollars(p)}` : ""}</button>
              );
            })}
          </div>
        );
      }
      case "quantity": {
        const obj = (v && typeof v === "object" ? (v as Record<string, number>) : {});
        const sum = Object.values(obj).reduce((s, n) => s + Number(n || 0), 0);
        const atMax = o.max_total != null && sum >= o.max_total;
        return (
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {(o.choices || []).map((c) => {
              const qty = Number(obj[c.value] || 0);
              return (
                <div key={c.value} style={{ display: "flex", alignItems: "center", gap: 10 }}>
                  <span style={{ flex: 1 }}>{c.label}{(o.price_info.byChoice[c.value] || 0) ? ` (${dollars(o.price_info.byChoice[c.value])} each)` : ""}</span>
                  <button type="button" className={styles.stepBtn} data-kind="minor" disabled={busy || qty <= 0} onClick={() => save(o, { ...obj, [c.value]: qty - 1 })} aria-label="Less"><span className={styles.stepGlyph}>−</span></button>
                  <span className={styles.teamStepperVal} style={{ minWidth: 20, textAlign: "center" }}>{qty}</span>
                  <button type="button" className={styles.stepBtn} data-kind="minor" disabled={busy || atMax} onClick={() => save(o, { ...obj, [c.value]: qty + 1 })} aria-label="More"><span className={styles.stepGlyph}>+</span></button>
                </div>
              );
            })}
            {o.max_total != null && <p className={styles.roundFormHint}>Up to {o.max_total} total.</p>}
          </div>
        );
      }
      case "text":
        return (
          <input className={styles.input} defaultValue={typeof v === "string" ? v : ""} disabled={busy} placeholder="Your answer"
            onBlur={(e) => { const t = e.target.value; if (t !== (typeof v === "string" ? v : "")) save(o, t); }} />
        );
      case "number":
        return (
          <input className={styles.input} type="number" defaultValue={typeof v === "number" ? String(v) : ""} disabled={busy} placeholder="0"
            onBlur={(e) => { const n = e.target.value === "" ? "" : Number(e.target.value); if (n !== v) save(o, n); }} />
        );
      default:
        return null;
    }
  }

  function optionItem(o: MemberOption) {
    return (
      <div key={o.id} className={styles.optItem}>
        <div className={styles.optItemHead}>
          {o.icon && <span aria-hidden style={{ fontSize: "1.1rem" }}>{o.icon}</span>}
          <div className={styles.optMain}>
            <span className={styles.optName}>{o.name}{o.is_required ? " *" : ""}</span>
            {o.description && <span className={styles.optSub}>{o.description}</span>}
          </div>
          <span className={styles.optPrice}>{headPrice(o)}</span>
        </div>
        <div className={styles.optItemControl}>{control(o)}</div>
      </div>
    );
  }

  const ungrouped = shown.filter((o) => !o.group_id || !groups.some((g) => g.id === o.group_id));

  return (
    <div className={styles.module}>
      <div className={styles.moduleHead}><span className={styles.sectionLabel}>Options</span></div>
      <div className={styles.optCard}>
        {!optionsOpen && <p className={styles.roundFormHint} style={{ marginTop: 0, marginBottom: 6 }}>Options are closed.</p>}

        {groups.map((g) => {
          const list = shown.filter((o) => o.group_id === g.id);
          if (list.length === 0) return null;
          return (
            <div key={g.id}>
              <p className={styles.optGroupLabel}>{g.icon ? `${g.icon} ` : ""}{g.name}</p>
              {list.map(optionItem)}
            </div>
          );
        })}

        {ungrouped.length > 0 && (
          <div>
            {groups.length > 0 && <p className={styles.optGroupLabel}>More</p>}
            {ungrouped.map(optionItem)}
          </div>
        )}

        <div className={styles.optTotalRow}>
          <span>Your total</span>
          <strong>{dollars(total)}</strong>
        </div>
      </div>
    </div>
  );
}

