"use client";

import { useState } from "react";
import Modal from "@/app/new/_components/Modal";
import styles from "@/app/new/new.module.css";
import { OptionControl, isEmptyValue, dollars, type MemberOption, type MemberGroup } from "./optionControls";
import { priceForValue } from "@/lib/v2/options";

/**
 * Home-page options nudge (#218). Options are NOT shown inline on the home — this
 * button is. It pulses while any required option is unanswered, and opens a wizard
 * that walks the member through each choice one at a time, ending in a summary.
 * Rendered only while options are open (before the deadline).
 */
export default function OptionsReminder({
  eventId, options, groups, initialSelections,
}: {
  eventId: string;
  options: MemberOption[];
  groups: MemberGroup[];
  initialSelections: Record<string, unknown>;
}) {
  const [sel, setSel] = useState<Record<string, unknown>>(initialSelections);
  const [open, setOpen] = useState(false);
  const [step, setStep] = useState(0);
  const [busyId, setBusyId] = useState<string | null>(null);

  const selectedOf = (o: MemberOption) => !isEmptyValue(o.option_type, sel[o.id]);
  const byId = new Map(options.map((o) => [o.id, o]));
  // Pure option-to-option dependency (v1 parity) — no attendance.
  const visible = (o: MemberOption): boolean => {
    if (!o.depends_on_option_id) return true;
    const p = byId.get(o.depends_on_option_id);
    return p ? selectedOf(p) : true;
  };
  // Walk options in the admin's arrangement: each section in order, then ungrouped —
  // matching the options page. (Raw array order interleaves sections.)
  const ordered = [
    ...groups.flatMap((g) => options.filter((o) => o.group_id === g.id)),
    ...options.filter((o) => !o.group_id || !groups.some((g) => g.id === o.group_id)),
  ];
  const shown = ordered.filter(visible);
  const incomplete = shown.filter((o) => o.is_required && isEmptyValue(o.option_type, sel[o.id]));
  const complete = incomplete.length === 0;

  async function save(o: MemberOption, value: unknown) {
    const prev = sel[o.id];
    const empty = isEmptyValue(o.option_type, value);
    setSel((s) => { const n = { ...s }; if (empty) delete n[o.id]; else n[o.id] = value; return n; });
    setBusyId(o.id);
    try {
      const url = `/api/v2/events/${eventId}/options/${o.id}/selection`;
      const res = empty ? await fetch(url, { method: "DELETE" }) : await fetch(url, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ value }) });
      if (!res.ok) throw new Error();
    } catch {
      setSel((s) => { const n = { ...s }; if (prev === undefined) delete n[o.id]; else n[o.id] = prev; return n; });
    } finally {
      setBusyId(null);
    }
  }

  if (shown.length === 0) return null;

  const total = shown.reduce((s, o) => s + priceForValue(o.option_type, sel[o.id], o.price_info), 0);
  const atSummary = step >= shown.length;
  const cur = shown[step];

  return (
    <div className={styles.module}>
      <button type="button" className={`${styles.optReminder}${complete ? "" : ` ${styles.optReminderPulse}`}`} onClick={() => { setStep(0); setOpen(true); }}>
