            <div className={styles.cscNav} style={{ marginTop: 18 }}>
              <button type="button" className={styles.cscNavBtn} disabled={step === 0} onClick={() => setStep(step - 1)}>‹ Back</button>
              <button type="button" className={styles.cscNavBtn} onClick={() => setStep(step + 1)}>{step === shown.length - 1 ? "Review ›" : "Next ›"}</button>
            </div>
          </div>
        ) : (
          <div>
            <p className={styles.sectionLabel}>Summary</p>
            <div className={styles.optList}>
              {shown.filter((o) => selectedOf(o)).map((o) => (
                <div key={o.id} className={styles.optRow}>
                  <div className={styles.optMain}><span className={styles.optName}>{o.icon ? `${o.icon} ` : ""}{o.name}</span></div>
                  <span className={styles.optPrice}>{(() => { const p = priceForValue(o.option_type, sel[o.id], o.price_info); return p ? dollars(p) : ""; })()}</span>
                </div>
              ))}
            </div>
            <div className={styles.optTotalRow}><span>Your total</span><strong>{dollars(total)}</strong></div>
            {!complete && <p className={styles.roundFormHint} style={{ marginTop: 8 }}>{incomplete.length} required option{incomplete.length === 1 ? "" : "s"} still need an answer.</p>}
            <div className={styles.cscNav} style={{ marginTop: 18 }}>
              <button type="button" className={styles.cscNavBtn} onClick={() => setStep(Math.max(0, shown.length - 1))}>‹ Back</button>
              <button type="button" className={styles.createBtn} onClick={() => setOpen(false)}>Done</button>
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
}

