"use client";

import { useState } from "react";
import Modal from "@/app/new/_components/Modal";
import styles from "@/app/new/new.module.css";
import { OptionControl, isEmptyValue, selectionIsActive, dollars, type MemberOption, type MemberGroup } from "./optionControls";
import { priceForValue } from "@/lib/v2/options";

/**
 * Home-page options nudge (#218). Options are NOT shown inline on the home — this
 * button is. It pulses while any required option is unanswered, and opens a wizard
 * that walks the member through each choice one at a time, ending in a summary.
 * Rendered only while options are open (before the deadline).
 */
export default function OptionsReminder({
  eventId, options, groups, initialSelections,
}: {
  eventId: string;
  options: MemberOption[];
  groups: MemberGroup[];
  initialSelections: Record<string, unknown>;
}) {
  const [sel, setSel] = useState<Record<string, unknown>>(initialSelections);
  const [open, setOpen] = useState(false);
  const [step, setStep] = useState(0);
  const [busyId, setBusyId] = useState<string | null>(null);

  const selectedOf = (o: MemberOption) => !isEmptyValue(o.option_type, sel[o.id]);
  const byId = new Map(options.map((o) => [o.id, o]));
  // Pure option-to-option dependency (v1 parity) — no attendance.
  const visible = (o: MemberOption): boolean => {
    if (!o.depends_on_option_id) return true;
    const p = byId.get(o.depends_on_option_id);
    return p ? selectionIsActive(p.option_type, sel[p.id]) : true;
  };
  // Walk options in the admin's arrangement: each section in order, then ungrouped —
  // matching the options page. (Raw array order interleaves sections.)
  const ordered = [
    ...groups.flatMap((g) => options.filter((o) => o.group_id === g.id)),
    ...options.filter((o) => !o.group_id || !groups.some((g) => g.id === o.group_id)),
  ];
  const shown = ordered.filter(visible);
  const incomplete = shown.filter((o) => o.is_required && isEmptyValue(o.option_type, sel[o.id]));
  const complete = incomplete.length === 0;

  async function save(o: MemberOption, value: unknown) {
    const prev = sel[o.id];
    const empty = isEmptyValue(o.option_type, value);
    setSel((s) => { const n = { ...s }; if (empty) delete n[o.id]; else n[o.id] = value; return n; });
    setBusyId(o.id);
    try {
      const url = `/api/v2/events/${eventId}/options/${o.id}/selection`;
      const res = empty ? await fetch(url, { method: "DELETE" }) : await fetch(url, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ value }) });
      if (!res.ok) throw new Error();
    } catch {
      setSel((s) => { const n = { ...s }; if (prev === undefined) delete n[o.id]; else n[o.id] = prev; return n; });
    } finally {
      setBusyId(null);
    }
  }

  if (shown.length === 0) return null;

  const total = shown.reduce((s, o) => s + priceForValue(o.option_type, sel[o.id], o.price_info), 0);
  const atSummary = step >= shown.length;
  const cur = shown[step];

  return (
    <div className={styles.module}>
      <button type="button" className={`${styles.optReminder}${complete ? "" : ` ${styles.optReminderPulse}`}`} onClick={() => { setStep(0); setOpen(true); }}>
        <span>
          <span className={styles.optReminderTitle}>{complete ? "Your options" : "Complete your options"}</span>
          <span className={styles.optReminderSub}>{complete ? "Review or update before the deadline" : `${incomplete.length} still need${incomplete.length === 1 ? "s" : ""} an answer`}</span>
        </span>
        <svg width="20" height="20" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.8} d="M9 5l7 7-7 7" /></svg>
      </button>

      <Modal open={open} title="Your options" onClose={() => setOpen(false)}>
        {!atSummary && cur ? (
          <div>
            <p className={styles.optWizStep}>{step + 1} of {shown.length}</p>
            <div className={styles.optItemHead}>
              {cur.icon && <span aria-hidden style={{ fontSize: "1.1rem" }}>{cur.icon}</span>}
              <div className={styles.optMain}>
                <span className={styles.optName}>{cur.name}{cur.is_required ? " *" : ""}</span>
                {cur.description && <span className={styles.optSub}>{cur.description}</span>}
              </div>
            </div>
            <div className={styles.optItemControl}><OptionControl option={cur} value={sel[cur.id]} disabled={busyId === cur.id} onChange={(v) => save(cur, v)} /></div>
            <div className={styles.cscNav} style={{ marginTop: 18 }}>
              <button type="button" className={styles.cscNavBtn} disabled={step === 0} onClick={() => setStep(step - 1)}>‹ Back</button>
              <button type="button" className={styles.cscNavBtn} onClick={() => setStep(step + 1)}>{step === shown.length - 1 ? "Review ›" : "Next ›"}</button>
            </div>
          </div>
        ) : (
          <div>
            <p className={styles.sectionLabel}>Summary</p>
            <div className={styles.optList}>
              {shown.filter((o) => selectedOf(o)).map((o) => (
                <div key={o.id} className={styles.optRow}>
                  <div className={styles.optMain}><span className={styles.optName}>{o.icon ? `${o.icon} ` : ""}{o.name}</span></div>
                  <span className={styles.optPrice}>{(() => { const p = priceForValue(o.option_type, sel[o.id], o.price_info); return p ? dollars(p) : ""; })()}</span>
                </div>
              ))}
            </div>
            <div className={styles.optTotalRow}><span>Your total</span><strong>{dollars(total)}</strong></div>
            {!complete && <p className={styles.roundFormHint} style={{ marginTop: 8 }}>{incomplete.length} required option{incomplete.length === 1 ? "" : "s"} still need an answer.</p>}
            <div className={styles.cscNav} style={{ marginTop: 18 }}>
              <button type="button" className={styles.cscNavBtn} onClick={() => setStep(Math.max(0, shown.length - 1))}>‹ Back</button>
              <button type="button" className={styles.createBtn} onClick={() => setOpen(false)}>Done</button>
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
}

