"use client";

import styles from "@/app/new/new.module.css";
import type { OptionType, OptionChoice, OptionPriceInfo } from "@/lib/v2/options";

export interface MemberOption {
  id: string;
  name: string;
  description: string | null;
  option_type: OptionType;
  choices: OptionChoice[] | null;
  is_required: boolean;
  max_total: number | null;
  icon: string | null;
  group_id: string | null;
  depends_on_option_id: string | null;
  allow_none?: boolean;       // show an admin-authored "none" opt-out (quantity)
  none_label?: string | null; // its label (defaults to "I'm not having any")
  price_info: OptionPriceInfo;
}
export interface MemberGroup { id: string; name: string; icon: string | null }

export function dollars(cents: number): string {
  return `$${(cents / 100).toLocaleString("en-US", { minimumFractionDigits: cents % 100 === 0 ? 0 : 2, maximumFractionDigits: 2 })}`;
}

export function isEmptyValue(type: OptionType, v: unknown): boolean {
  switch (type) {
    case "checkbox": return v !== true;
    case "select": return !(typeof v === "string" && v.length > 0);
    case "multi_select": return !(Array.isArray(v) && v.length > 0);
    // Any non-null object is an answer — {} is the "I'm not having any" opt-out.
    case "quantity": return !(v !== null && v !== undefined && typeof v === "object" && !Array.isArray(v));
    case "text": return !(typeof v === "string" && v.trim().length > 0);
    case "number": return v === null || v === undefined || v === "";
    default: return true;
  }
}

/**
 * Whether a selection is "active" for the purpose of REVEALING dependent options.
 * Stricter than "answered": a quantity option opted to "none" ({}) is answered but not
 * active, so it doesn't reveal its dependents (v1 keys dependency off a positive total).
 */
export function selectionIsActive(type: OptionType, v: unknown): boolean {
  if (type === "quantity") {
    return !!v && typeof v === "object" && !Array.isArray(v) && Object.values(v as Record<string, number>).some((n) => Number(n) > 0);
  }
  return !isEmptyValue(type, v);
}

/** The per-type control for one option. Decoupled from persistence: calls onChange
 *  with the new value; the parent saves. `disabled` locks it (closed / read-only). */
export function OptionControl({ option: o, value: v, disabled, onChange }: {
  option: MemberOption; value: unknown; disabled: boolean; onChange: (v: unknown) => void;
}) {
  switch (o.option_type) {
    // Binary → a toggle switch (v1 parity).
    case "checkbox": {
      const on = v === true;
      return (
        <button type="button" className={styles.optChoiceRow} data-on={on || undefined} disabled={disabled} onClick={() => onChange(on ? false : true)}>
          <span className={styles.optChoiceLabel}>{on ? "Selected" : "Tap to select"}</span>
          <span className={styles.optSwitch} data-on={on || undefined} aria-hidden><span className={styles.optSwitchKnob} /></span>
        </button>
      );
    }
    // Single choice → radio buttons (v1 parity).
    case "select":
      return (
        <div className={styles.optChoiceList}>
          {(o.choices || []).map((c) => {
            const on = v === c.value;
            const p = o.price_info.byChoice[c.value] || 0;
            return (
              <button key={c.value} type="button" className={styles.optChoiceRow} data-on={on || undefined} disabled={disabled}
                onClick={() => onChange(on ? "" : c.value)}>
                <span className={styles.optChoiceMain}>
                  <span className={styles.optRadio} data-on={on || undefined} aria-hidden />
                  <span className={styles.optChoiceLabel}>{c.label}</span>
                </span>
                {p ? <span className={styles.optChoicePrice}>{dollars(p)}</span> : null}
              </button>
            );
          })}
        </div>
      );
    // Many choices → checkboxes (v1 parity).
    case "multi_select": {
      const arr = Array.isArray(v) ? (v as string[]) : [];
      return (
        <div className={styles.optChoiceList}>
          {(o.choices || []).map((c) => {
            const on = arr.includes(c.value);
            const p = o.price_info.byChoice[c.value] || 0;
            return (
              <button key={c.value} type="button" className={styles.optChoiceRow} data-on={on || undefined} disabled={disabled}
                onClick={() => onChange(on ? arr.filter((x) => x !== c.value) : [...arr, c.value])}>
                <span className={styles.optChoiceMain}>
                  <span className={styles.optCheckbox} data-on={on || undefined} aria-hidden>
                    {on && <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3.5} strokeLinecap="round" strokeLinejoin="round"><path d="M5 13l4 4L19 7" /></svg>}
                  </span>
                  <span className={styles.optChoiceLabel}>{c.label}</span>
                </span>
                {p ? <span className={styles.optChoicePrice}>{dollars(p)}</span> : null}
              </button>
            );
          })}
        </div>
      );
    }
    case "quantity": {
      const obj = (v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, number>) : {});
      const sum = Object.values(obj).reduce((s, n) => s + Number(n || 0), 0);
      const atMax = o.max_total != null && sum >= o.max_total;
      // Setting a choice's count: drop zero keys; no positive keys left → unanswered (null).
      const setQty = (cv: string, next: number) => {
        const nextObj = { ...obj };
        if (next <= 0) delete nextObj[cv]; else nextObj[cv] = next;
        onChange(Object.values(nextObj).some((n) => Number(n) > 0) ? nextObj : null);
      };
      // Answered "none": a present object that sums to 0 (the opt-out below).
      const optedNone = v !== null && v !== undefined && typeof v === "object" && !Array.isArray(v) && sum === 0;
      return (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {(o.choices || []).map((c) => {
            const qty = Number(obj[c.value] || 0);
            const per = o.price_info.byChoice[c.value] || 0;
            return (
              <div key={c.value} style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <span style={{ flex: 1 }}>{c.label}{per ? ` (${dollars(per)} each)` : ""}</span>
                <button type="button" className={styles.stepBtn} data-kind="minor" disabled={disabled || qty <= 0} onClick={() => setQty(c.value, qty - 1)} aria-label="Less"><span className={styles.stepGlyph}>−</span></button>
                <span className={styles.teamStepperVal} style={{ minWidth: 20, textAlign: "center" }}>{qty}</span>
                <button type="button" className={styles.stepBtn} data-kind="minor" disabled={disabled || atMax} onClick={() => setQty(c.value, qty + 1)} aria-label="More"><span className={styles.stepGlyph}>+</span></button>
              </div>
            );
          })}
          {o.max_total != null && <p className={styles.roundFormHint}>Up to {o.max_total} total.</p>}
          {/* Required quantity options get an explicit opt-out so "none" is a valid answer. */}
          {o.is_required && (
            <button type="button" className={styles.optChoiceRow} data-on={optedNone || undefined} disabled={disabled}
              onClick={() => onChange(optedNone ? null : {})}>
              <span className={styles.optChoiceMain}>
                <span className={styles.optCheckbox} data-on={optedNone || undefined} aria-hidden>
                  {optedNone && <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3.5} strokeLinecap="round" strokeLinejoin="round"><path d="M5 13l4 4L19 7" /></svg>}
                </span>
                <span className={styles.optChoiceLabel}>I&apos;m not having any</span>
              </span>
            </button>
          )}
        </div>
      );
    }
    case "text":
      return (
        <input className={styles.input} defaultValue={typeof v === "string" ? v : ""} disabled={disabled} placeholder="Your answer"
          onBlur={(e) => { const t = e.target.value; if (t !== (typeof v === "string" ? v : "")) onChange(t); }} />
      );
    case "number":
      return (
        <input className={styles.input} type="number" defaultValue={typeof v === "number" ? String(v) : ""} disabled={disabled} placeholder="0"
          onBlur={(e) => { const n = e.target.value === "" ? "" : Number(e.target.value); if (n !== v) onChange(n); }} />
      );
    default:
      return null;
  }
}

import { redirect } from "next/navigation";
import { getPlatformContext } from "@/lib/v2/context";
import { v2ServerClient } from "@/lib/v2/supabase";
import { v2Now } from "@/lib/v2/simulator";
import { OPTION_SELECT, loadOptionChoicePrices, tripCostCents, loadOptionSettings, selectionsStillOpen, type Option } from "@/lib/v2/options";
import { loadResolvedFeatures } from "@/lib/v2/features-server";
import { isFeatureActive, featureHasOpened } from "@/lib/v2/features";
import OptionsModule from "../OptionsModule";
import styles from "@/app/new/new.module.css";

/**
 * Member options page (#218) — the full list, reached from the "Everything" menu.
 * Editable while open; read-only once the deadline passes (is_open but expired).
 * Not reachable when options are closed (is_open=false) — the menu hides it then.
 */
export default async function MemberOptionsPage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;
  const ctx = await getPlatformContext();
  if (!ctx) redirect("/new/signup");
  const org = ctx.orgs.find((o) => o.slug === slug);
  if (!org) redirect("/new");

  const supabase = await v2ServerClient();
  const { data: ev } = await supabase
    .from("v2_events").select("id, name").eq("org_id", org.id).eq("status", "active").order("start_date", { ascending: false }).limit(1).maybeSingle();
  if (!ev) redirect(`/new/${slug}`);
  const eventId = ev.id as string;

  // Options scheduling lives in the Features availability window now.
  const isAdmin = org.role === "owner" || org.role === "admin";
  const resolved = await loadResolvedFeatures(supabase, org.id, eventId);
  const feat = resolved.find((r) => r.def.key === "options") || null;
  const nowDate = await v2Now();
  if (!feat || !featureHasOpened(feat, isAdmin, nowDate)) redirect(`/new/${slug}`); // not yet open / closed / off

  // Trip Cost is a normal selectable option (v1 parity) — include it; its price is
  // derived from the included_in_trip_cost catalog, not from bundled cost items.
  const [{ data: optRows }, { data: grpRows }, { data: selRows }] = await Promise.all([
    supabase.from("v2_options").select(OPTION_SELECT).eq("event_id", eventId).order("sort_order"),
    supabase.from("v2_option_groups").select("id, name, icon, sort_order").eq("event_id", eventId).order("sort_order"),
    supabase.from("v2_user_option_selections").select("option_id, value").eq("event_id", eventId).eq("user_id", ctx.userId),
  ]);
  const options = (optRows || []) as Option[];
  const [priceInfo, tc, optSettings] = await Promise.all([
    loadOptionChoicePrices(supabase, options.map((o) => o.id)),
    tripCostCents(supabase, eventId),
    loadOptionSettings(supabase, eventId),
  ]);
  // Editable only while the feature window is active AND the close cutoff hasn't passed.
  const open = isFeatureActive(feat, isAdmin, nowDate) && selectionsStillOpen(optSettings, nowDate.getTime());

  const memberOptions = options
    // A $0 Trip Cost (nothing marked for it yet) isn't worth showing as an option.
    .filter((o) => o.option_type !== "trip_cost" || tc > 0)
    .map((o) => {
      const isTrip = o.option_type === "trip_cost";
      return {
        id: o.id, name: o.name, description: o.description,
        option_type: (isTrip ? "checkbox" : o.option_type) as Option["option_type"],
        choices: o.choices, is_required: o.is_required, max_total: o.max_total, icon: o.icon, group_id: o.group_id,
        depends_on_option_id: o.depends_on_option_id,
        price_info: isTrip ? { whole: tc, byChoice: {} } : (priceInfo.get(o.id) || { whole: 0, byChoice: {} }),
      };
    });
  const selections: Record<string, unknown> = {};
  for (const s of (selRows as { option_id: string; value: unknown }[] | null) ?? []) selections[s.option_id] = s.value;
  const groups = ((grpRows as { id: string; name: string; icon: string | null }[] | null) ?? []).map((g) => ({ id: g.id, name: g.name, icon: g.icon }));

  return (
    <div className={`${styles.page} ${styles.orgPage}`}>
      <h1 className={styles.title}>Options</h1>
      <p className={styles.lede} style={{ marginTop: 6 }}>
        {open ? "Your add-ons for the event. Change them any time before the deadline." : "Selections are closed. Here's a summary of your choices."}
      </p>
      <OptionsModule
        eventId={eventId}
        options={memberOptions}
        groups={groups}
        initialSelections={selections}
        optionsOpen={open}
      />
    </div>
  );
}

