254	  async function changeType(forOption: OptionData | null, next: OptionType) {
255	    setOptType(next);
256	    if (!forOption || busy) return;
257	    setBusy(true); setError(null);
258	    const before = options;
259	    try {
260	      const res = await fetch(`${optionsBase}/${forOption.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ option_type: next }) });
261	      if (!res.ok) throw new Error();
262	      const saved = (await res.json()).option as OptionData;
263	      setOptions((prev) => prev.map((x) => (x.id === forOption.id ? { ...x, option_type: saved.option_type, choices: saved.choices } : x)));
264	    } catch { setOptions(before); setOptType(forOption.option_type); setError("Could not change type"); }
265	    finally { setBusy(false); }
266	  }
267	  const addChoice = () => setChoices((c) => [...c, { label: "", value: "" }]);
268	  const updateChoice = (i: number, label: string) => setChoices((c) => c.map((x, j) => (j === i ? { ...x, label } : x)));
269	  const removeChoice = (i: number) => setChoices((c) => c.filter((_, j) => j !== i));

